/* ──────────────────────────────────────────────────────────────────────────
   learnroman-marta.js — „Marta in München" · Zielsprache DEUTSCH
   Muttersprachen es + en (na/tr/teaser als {es, en}). Fester Inhalt, kein API-Call.
   Aufbau wie learnroman-lukas.js (Leo, 15.10.2026): 21 Stationen —
   Teil I = die 10 A1-Szenen des Geführten Gesprächs (lernpfad-daten-de.js a1.*),
   Teil II = dieselben 10 Themen auf A2, Epilog = deutsche Prosa ohne Brücke.
   Motor: die Anmeldung (Wohnungsgeberbestätigung) bis 31. Oktober.
   Ersetzt das alte „Marta en Berlín" (Text in der Git-Historie).
   ────────────────────────────────────────────────────────────────────────── */
/* ──────────────────────────────────────────────────────────────────────────
   lr-parts/marta-1.js — „Marta in München" · Teil I · fundament · „Servus, Marta"
   Zielsprache Deutsch · Muttersprachen es (castellano de España), en (British).
   Stationen 1–10 = die zehn A1-Szenen des Lernpfads (SpikiuLernpfadDE a1.*).
   N(es, en) = Erzählung in der Muttersprache · Z(de, es, en) = Deutsch + Brücken.
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_MARTA = w.__LR_PARTS_MARTA || {};
  function N(a, b) { return { na: { es: a, en: b } }; }
  function Z(z, a, b) { var o = { z: z }; if (a) o.tr = { es: a, en: b }; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, teaserA, teaserB, body) {
    return { level: level, n: n, thema: thema, title: title, teaser: { es: teaserA, en: teaserB }, body: body };
  }

  K.teil1 = [

  // ── Station 1 · TAXI ────────────────────────────────────────────────
  S('fundament', 1, 'taxi', "Sind Sie frei?",
    "Marta aterriza en Múnich con una chaqueta vaquera y nueve grados fuera — y un correo le exige una palabra de veinticuatro letras.",
    "Marta lands in Munich wearing a denim jacket in nine degrees — and an email demands a word with twenty-four letters.",
  [
    N("Aeropuerto de Múnich, un martes de principios de octubre, las once menos cuarto de la noche. Las puertas automáticas se abren y el aire de fuera le da a Marta una bofetada.",
      "Munich Airport, a Tuesday in early October, a quarter to eleven at night. The automatic doors open and the air outside slaps Marta in the face."),
    N("Marta Ruiz, veinticuatro años, de Sevilla. Un máster en la TU de Múnich, un contrato de ayudante en la cátedra, una maleta verde. Esta mañana, en Sevilla, hacía veintinueve grados. Lleva una chaqueta vaquera. Solo eso.",
      "Marta Ruiz, twenty-four, from Seville. A master's at the TU in Munich, a job as a student assistant at the department, a green suitcase. This morning in Seville it was twenty-nine degrees. She is wearing a denim jacket. That's all."),
    Z("Es ist kalt. Es ist sehr kalt.", "Hace frío. Hace mucho frío.", "It's cold. It's very cold."),
    Z("Vor dem Terminal stehen viele Taxis. Sie sind hell und sehr sauber.", "Delante de la terminal hay muchos taxis. Son claros y están muy limpios.", "There are lots of taxis in front of the terminal. They're pale and very clean."),
    N("En el primero, una mujer de unos sesenta años, pelo corto y gris, se pinta los labios en el retrovisor. Rojo intenso. Sin ninguna prisa. Marta respira hondo. La primera frase la ha practicado en el avión.",
      "In the first one, a woman of about sixty, short grey hair, is putting on lipstick in the rear-view mirror. Bright red. In no hurry at all. Marta takes a deep breath. She practised the first sentence on the plane."),
    Z("—Entschuldigung. Sind Sie frei?", "Perdone. ¿Está libre?", "Excuse me. Are you free?"),
    Z("—Moment.", "Un momento.", "Just a moment."),
    N("La mujer termina el labio de abajo, aprieta los labios, se mira otra vez. Solo entonces baja la ventanilla.",
      "The woman finishes her lower lip, presses her lips together, checks again. Only then does she wind down the window."),
    Z("—Ja. Steigen Sie ein. Haben Sie Gepäck dabei?", "Sí. Suba. ¿Lleva equipaje?", "Yes. Get in. Have you got any luggage?"),
    Z("—Ja, einen Koffer. Er ist sehr schwer.", "Sí, una maleta. Pesa mucho.", "Yes, one suitcase. It's very heavy."),
    Z("Die Fahrerin steigt aus. Sie legt den Koffer in den Kofferraum.", "La taxista se baja. Mete la maleta en el maletero.", "The driver gets out. She puts the suitcase in the boot."),
    N("Con una sola mano. Como si fuera una bolsa de pan.",
      "With one hand. As if it were a bag of bread."),
    Z("—Schwer? Ach was. Wohin soll es gehen?", "¿Pesada? Qué va. ¿Adónde vamos?", "Heavy? Nonsense. Where to?"),
    N("Marta le enseña el móvil. La dirección se la mandó Aylin, su futura compañera de piso, con tres copos de nieve. Ahora los entiende.",
      "Marta shows her the phone. Aylin, her future flatmate, sent her the address, with three snowflakes. Now she understands them."),
    Z("—Zu dieser Adresse, bitte. Wörthstraße zwölf.", "A esta dirección, por favor. Wörthstraße, número doce.", "To this address, please. Wörthstraße, number twelve."),
    Z("—Haidhausen. Passt.", "Haidhausen. Vale.", "Haidhausen. Fine."),
    Z("Im Taxi ist es warm. Marta hält die Hände an die Heizung.", "Dentro del taxi hace calor. Marta pone las manos junto a la calefacción.", "It's warm in the taxi. Marta holds her hands up to the heater."),
    Z("—Woher kommen Sie?", "¿De dónde es usted?", "Where are you from?"),
    Z("—Aus Spanien. Aus Sevilla.", "De España. De Sevilla.", "From Spain. From Seville."),
    Z("—Spanierin! Und nur eine Jacke? Im Oktober?", "¡Española! ¿Y solo una chaqueta? ¿En octubre?", "A Spaniard! And just a jacket? In October?"),
    Z("—In Sevilla ist es warm.", "En Sevilla hace calor.", "It's warm in Seville."),
    Z("—Hier ned, Spanierin. Hier ned. Ich bin die Gerti.", "Aquí no, española. Aquí no. Yo soy Gerti.", "Not here, Spaniard. Not here. I'm Gerti."),
    N("«Ned» es «nicht» en bávaro, le explicará Aylin mañana. Marta ya tiene apodo y todavía no ha salido del aeropuerto.",
      "“Ned” is Bavarian for “nicht”, Aylin will explain tomorrow. Marta already has a nickname and she hasn't even left the airport."),
    N("Autopista, oscuridad. En la radio, una canción alemana antigua; Gerti canta la mitad de la letra. El móvil vibra: un correo de Recursos Humanos de la universidad.",
      "Motorway, darkness. An old German song on the radio; Gerti sings half the lyrics. The phone buzzes: an email from the university's HR department."),
    N("«Para pagarle el sueldo necesitamos su número fiscal (Steuer-ID). Lo recibirá tras empadronarse. Empadrónese antes del 31 de octubre. Necesitará: cita en el Bürgerbüro, pasaporte y la Wohnungsgeberbestätigung firmada por su arrendador.»",
      "“To pay your salary we need your tax ID (Steuer-ID). You will receive it after registering your address. Please register by 31 October. You will need: an appointment at the Bürgerbüro, your passport and the Wohnungsgeberbestätigung signed by your landlord.”"),
    N("Wohnungsgeberbestätigung. Marta cuenta las letras con el dedo sobre la pantalla. Veinticuatro. Es más larga que su nombre completo con los dos apellidos.",
      "Wohnungsgeberbestätigung. Marta counts the letters with her finger on the screen. Twenty-four. It's longer than her full name with both surnames."),
    Z("—Entschuldigung. Was ist eine Wohnungs… geber… bestätigung?", "Perdone. ¿Qué es una Wohnungs… geber… bestätigung?", "Excuse me. What is a Wohnungs… geber… bestätigung?"),
    Z("—Ein Papier. Vom Vermieter. Mit Unterschrift.", "Un papel. Del casero. Con firma.", "A piece of paper. From the landlord. With a signature."),
    Z("—Nur ein Papier?", "¿Solo un papel?", "Just a piece of paper?"),
    Z("—In Deutschland gibt es kein »nur ein Papier«, Spanierin.", "En Alemania no existe «solo un papel», española.", "In Germany there's no such thing as “just a piece of paper”, Spaniard."),
    N("Gerti se ríe. El pintalabios aguanta. Luces, un tranvía vacío, un río ancho y negro: el Isar.",
      "Gerti laughs. The lipstick holds. Lights, an empty tram, a wide black river: the Isar."),
    Z("Das Taxi hält. Die Häuser sind alt und hoch.", "El taxi para. Las casas son antiguas y altas.", "The taxi stops. The houses are old and tall."),
    Z("—So. Da sind wir. Achtundsechzig Euro.", "Bueno. Ya estamos. Sesenta y ocho euros.", "Right. Here we are. Sixty-eight euros."),
    N("Marta le da setenta. Esta frase también la practicó. Es su favorita: suena a alguien que está de acuerdo con todo el país.",
      "Marta gives her seventy. She practised this sentence too. It's her favourite: it sounds like someone who agrees with the whole country."),
    Z("—Stimmt so.", "Quédese con la vuelta.", "Keep the change."),
    Z("—Danke, Spanierin. Und kaufen Sie eine Jacke!", "Gracias, española. ¡Y cómprese una chaqueta!", "Thanks, Spaniard. And buy yourself a jacket!"),
    N("Arriba se abre una ventana. Un chico en camiseta, con una taza en la mano, saluda con el brazo entero.",
      "Above, a window opens. A young man in a T-shirt, a mug in his hand, waves with his whole arm."),
    Z("—Servus! Du bist Marta, oder? Zweiter Stock!", "¡Hola! Tú eres Marta, ¿no? ¡Segundo piso!", "Hi there! You're Marta, right? Second floor!"),
    N("Servus. Esa palabra no venía en su libro. Marta mira la maleta, luego la puerta, luego otra vez el correo.",
      "Servus. That word wasn't in her textbook. Marta looks at the suitcase, then at the door, then at the email again."),
    Z("Wohnungsgeberbestätigung."),
    N("Veinticuatro letras. Veintitrés días.",
      "Twenty-four letters. Twenty-three days.")
  ]),

  // ── Station 2 · CAFÉ ────────────────────────────────────────────────
  S('fundament', 2, 'cafe', "Zum Hiertrinken",
    "El primer café en la panadería de la señora Schmid: un panecillo que en Múnich se llama de otra manera y una cita a una hora imposible.",
    "The first coffee at Frau Schmid's bakery: a bread roll that has a different name in Munich, and an appointment at an impossible hour.",
  [
    N("A la mañana siguiente, en la cocina, hay una nota pegada a la cafetera: «Kaffee ist alle. Sorry! J.» Jonas, el chico de la ventana, conduce el tranvía. Su turno empieza a las cinco. El café, por lo visto, también.",
      "The next morning, in the kitchen, there's a note stuck to the coffee machine: “Kaffee ist alle. Sorry! J.” Jonas, the young man at the window, drives a tram. His shift starts at five. So, apparently, does the coffee."),
    N("Aylin entra en pijama de quirófano verde y con el pelo recogido en un moño de emergencia. Veintiséis años, estudia Medicina, es de Augsburgo. Lee la nota y suspira.",
      "Aylin comes in wearing green surgical scrubs, her hair in an emergency bun. Twenty-six, studying medicine, from Augsburg. She reads the note and sighs."),
    Z("—Guten Morgen! Kein Kaffee. Wir gehen runter. Zu Frau Schmid.", "¡Buenos días! No hay café. Bajamos. A la panadería de la señora Schmid.", "Good morning! No coffee. We're going downstairs. To Frau Schmid's."),
    N("En la planta baja del edificio hay una panadería con cuatro mesitas. Huele a pan caliente y a canela. Detrás del mostrador, una señora con gafas colgadas de una cadenita mira a Marta como un profesor el primer día de clase.",
      "On the ground floor of the building there is a bakery with four little tables. It smells of warm bread and cinnamon. Behind the counter, a woman with glasses on a chain looks at Marta like a teacher on the first day of school."),
    Z("—Grüß Gott. Was darf's sein?", "Buenos días. ¿Qué le pongo?", "Good morning. What can I get you?"),
    N("«Grüß Gott», susurra Aylin, «es buenos días en Baviera. Literalmente: saluda a Dios.» Marta decide que ya saludará a Dios otro día. Hoy solo quiere café.",
      "“Grüß Gott,” Aylin whispers, “is good morning in Bavaria. Literally: greet God.” Marta decides she will greet God another day. Today she just wants coffee."),
    Z("—Einen Kaffee, bitte. Und zwei Brötchen.", "Un café, por favor. Y dos panecillos.", "A coffee, please. And two bread rolls."),
    Z("—Semmeln, meinen Sie.", "Semmeln, querrá decir.", "Semmeln, you mean."),
    Z("—Semmeln?", "¿Semmeln?", "Semmeln?"),
    Z("—In München sagt man Semmel. Zum Hiertrinken oder zum Mitnehmen?", "En Múnich se dice Semmel. ¿Para tomar aquí o para llevar?", "In Munich we say Semmel. To have here or to take away?"),
    Z("—Zum Hiertrinken, bitte. Mit Milch, ohne Zucker.", "Para tomar aquí, por favor. Con leche, sin azúcar.", "To have here, please. With milk, no sugar."),
    Z("—Kommt sofort. Sonst noch etwas?", "Enseguida. ¿Algo más?", "Coming right up. Anything else?"),
    Z("—Für mich einen Tee, bitte. Und ein Glas Wasser.", "Para mí, un té, por favor. Y un vaso de agua.", "A tea for me, please. And a glass of water."),
    N("Se sientan junto a la ventana. Marta no se quita la bufanda. Aylin la mira por encima de la taza y no dice nada. Luego Marta le enseña el correo. Aylin lo lee y saca un bolígrafo.",
      "They sit by the window. Marta keeps her scarf on. Aylin looks at her over her cup and says nothing. Then Marta shows her the email. Aylin reads it and takes out a pen."),
    Z("—Okay. Du brauchst drei Dinge.", "Vale. Necesitas tres cosas.", "Okay. You need three things."),
    Z("—Erstens: einen Termin im Bürgerbüro. Zweitens: deinen Pass.", "Primero: una cita en el Bürgerbüro. Segundo: tu pasaporte.", "First: an appointment at the Bürgerbüro. Second: your passport."),
    Z("—Und drittens: die Wohnungsgeberbestätigung. Von Frau Ostermeier.", "Y tercero: la confirmación de la casera. De la señora Ostermeier.", "And third: the landlord's confirmation. From Frau Ostermeier."),
    Z("—Wer ist Frau Ostermeier?", "¿Quién es la señora Ostermeier?", "Who is Frau Ostermeier?"),
    Z("—Die Wohnung gehört ihr. Sie ist einundachtzig. Sie macht eine Kur in Bad Tölz.", "El piso es suyo. Tiene ochenta y un años. Está en un balneario en Bad Tölz.", "The flat is hers. She's eighty-one. She's at a spa in Bad Tölz."),
    Z("—Dann schreibe ich ihr eine E-Mail.", "Entonces le escribo un correo.", "Then I'll write her an email."),
    Z("—Frau Ostermeier macht keine E-Mail. Sie hat ein Telefon. Mit Kabel.", "La señora Ostermeier no hace correos. Tiene un teléfono. Con cable.", "Frau Ostermeier doesn't do email. She has a telephone. With a cord."),
    N("Aylin ya está buscando citas en la web del ayuntamiento. Desliza. Desliza. Desliza. Todo lleno hasta diciembre. Y de pronto:",
      "Aylin is already looking for appointments on the city website. She scrolls. And scrolls. And scrolls. Everything booked until December. And suddenly:"),
    Z("—Hier! Ein Termin. Donnerstag, der vierundzwanzigste Oktober, acht Uhr fünfzehn.", "¡Aquí! Una cita. Jueves, veinticuatro de octubre, a las ocho y cuarto.", "Here! An appointment. Thursday, the twenty-fourth of October, quarter past eight."),
    Z("—Acht Uhr fünfzehn? Am Morgen?", "¿A las ocho y cuarto? ¿De la mañana?", "Quarter past eight? In the morning?"),
    N("En Sevilla, a las ocho y cuarto solo están despiertos los panaderos y las monjas.",
      "In Seville, at quarter past eight only bakers and nuns are awake."),
    Z("—In Deutschland ist acht Uhr fünfzehn um acht Uhr fünfzehn. Nicht um acht Uhr zwanzig.", "En Alemania, las ocho y cuarto son a las ocho y cuarto. No a las ocho y veinte.", "In Germany, quarter past eight is at quarter past eight. Not at twenty past."),
    N("Aylin reserva. Marta mira por la ventana: la gente cruza la calle solo con el semáforo en verde, aunque no venga ningún coche.",
      "Aylin books it. Marta looks out of the window: people only cross the street when the light is green, even when there are no cars."),
    Z("—Zahlen, bitte. Was macht das?", "La cuenta, por favor. ¿Cuánto es?", "Can we pay, please? How much is that?"),
    Z("—Kaffee, Tee, zwei Semmeln. Zusammen sieben Euro.", "Café, té, dos Semmeln. En total, siete euros.", "Coffee, tea, two Semmeln. Seven euros altogether."),
    N("Marta paga con un billete de diez. Esta vez lo dice sin pensarlo: «Stimmt so.» La señora Schmid asiente una sola vez. Es difícil saber si eso es simpatía.",
      "Marta pays with a ten-euro note. This time she says it without thinking: “Stimmt so.” Frau Schmid nods just once. It's hard to tell whether that is warmth."),
    Z("—Danke. Bis morgen. Zwei Semmeln?", "Gracias. Hasta mañana. ¿Dos Semmeln?", "Thank you. See you tomorrow. Two Semmeln?"),
    Z("—Zwei Brötchen.", "Dos panecillos.", "Two bread rolls."),
    N("La señora Schmid se sube las gafas. Aylin tira de Marta hacia la calle antes de que empiece la guerra.",
      "Frau Schmid pushes her glasses up. Aylin pulls Marta out onto the street before the war can begin."),
    Z("Ein Termin, ein Pass und eine Unterschrift. Und die Unterschrift ist in Bad Tölz.", "Una cita, un pasaporte y una firma. Y la firma está en Bad Tölz.", "An appointment, a passport and a signature. And the signature is in Bad Tölz.")
  ]),

  // ── Station 3 · EINKAUFEN ───────────────────────────────────────────
  S('fundament', 3, 'einkaufen', "Ein halbes Pfund Käse",
    "En el Viktualienmarkt, una quesera reconoce un nombre — y Marta consigue algo mejor que queso: un número de teléfono.",
    "At the Viktualienmarkt, a cheese seller recognises a name — and Marta gets something better than cheese: a phone number.",
  [
    N("Sábado por la mañana. Jonas tiene el día libre y ha decidido enseñarle a Marta «el corazón de Múnich». El corazón de Múnich, por lo visto, es un mercado.",
      "Saturday morning. Jonas has the day off and has decided to show Marta “the heart of Munich”. The heart of Munich, apparently, is a market."),
    Z("Der Viktualienmarkt ist groß. Es gibt Obst, Gemüse, Brot, Fisch und Käse.", "El Viktualienmarkt es grande. Hay fruta, verdura, pan, pescado y queso.", "The Viktualienmarkt is big. There's fruit, vegetables, bread, fish and cheese."),
    N("En medio del mercado hay un mástil enorme pintado de blanco y azul, con figuritas de madera. Jonas dice que se llama Maibaum. Marta dice que en octubre no hay mayo. Jonas dice que en Baviera siempre hay mayo. Marta lleva dos jerséis.",
      "In the middle of the market stands a huge pole painted white and blue, with little wooden figures. Jonas says it's called a Maibaum, a maypole. Marta says there's no May in October. Jonas says in Bavaria there's always May. Marta is wearing two jumpers."),
    N("La lista de la compra es de Aylin: manzanas y queso. Al lado, Aylin ha dibujado un corazón y ha escrito «Tüte mitnehmen!». Marta tiene una bolsa de tela en el bolsillo. Ya empieza a parecer alemana.",
      "The shopping list is Aylin's: apples and cheese. Next to it Aylin has drawn a heart and written “Tüte mitnehmen!” — bring a bag. Marta has a cloth bag in her pocket. She is already starting to look German."),
    Z("—Guten Morgen! Wer ist der Nächste?", "¡Buenos días! ¿Quién es el siguiente?", "Good morning! Who's next?"),
    Z("—Ich. Ein Kilo Äpfel, bitte.", "Yo. Un kilo de manzanas, por favor.", "Me. A kilo of apples, please."),
    Z("—Gerne. Sonst noch einen Wunsch?", "Muy bien. ¿Desea algo más?", "Certainly. Anything else?"),
    Z("—Nein, danke.", "No, gracias.", "No, thank you."),
    N("En el puesto de al lado, el queso. Montañas de queso. Ruedas tan grandes como neumáticos. Marta lee el papel de Aylin: «ein halbes Pfund Emmentaler».",
      "At the next stall, the cheese. Mountains of cheese. Wheels as big as car tyres. Marta reads Aylin's note: “ein halbes Pfund Emmentaler”."),
    Z("—Jonas, was ist ein Pfund? Wie in London?", "Jonas, ¿qué es un Pfund? ¿Como en Londres?", "Jonas, what's a Pfund? Like in London?"),
    Z("—Ein Pfund sind fünfhundert Gramm. Ein halbes Pfund sind zweihundertfünfzig.", "Un Pfund son quinientos gramos. Medio Pfund, doscientos cincuenta.", "A Pfund is five hundred grams. Half a Pfund is two hundred and fifty."),
    N("Detrás del mostrador está una mujer de unos ochenta años, con mejillas rojas, un delantal de rayas y unos brazos que han cortado mucho queso. En el cartel pone: «Käse von der Vroni».",
      "Behind the counter stands a woman of about eighty, with red cheeks, a striped apron and arms that have cut a great deal of cheese. The sign says: “Käse von der Vroni”."),
    Z("—Ein halbes Pfund Emmentaler, bitte. Was kostet das?", "Medio Pfund de emmental, por favor. ¿Cuánto cuesta?", "Half a Pfund of Emmental, please. How much is that?"),
    Z("—Vier Euro achtzig. Brauchen Sie eine Tüte?", "Cuatro euros ochenta. ¿Necesita bolsa?", "Four euros eighty. Do you need a bag?"),
    Z("—Nein, danke. Ich habe eine Tasche.", "No, gracias. Tengo una bolsa.", "No, thank you. I've got a bag."),
    N("Mientras Vroni corta, Jonas le pregunta a Marta por la firma. Marta contesta en voz alta, con el nombre completo, como en un examen.",
      "While Vroni cuts, Jonas asks Marta about the signature. Marta answers loudly, with the full name, as if in an exam."),
    Z("—Frau Ostermeier ist in Bad Tölz. Sie macht eine Kur.", "La señora Ostermeier está en Bad Tölz. Está en un balneario.", "Frau Ostermeier is in Bad Tölz. She's at a spa."),
    N("El cuchillo de Vroni se para en el aire.",
      "Vroni's knife stops in mid-air."),
    Z("—Ostermeier? Die Rosi? Aus der Wörthstraße?", "¿Ostermeier? ¿La Rosi? ¿La de la Wörthstraße?", "Ostermeier? Rosi? From Wörthstraße?"),
    Z("—Ja! Kennen Sie sie?", "¡Sí! ¿La conoce?", "Yes! Do you know her?"),
    Z("—Die Rosi und ich waren zusammen in der Schule. Sie hat immer bei mir abgeschrieben.", "La Rosi y yo íbamos juntas al colegio. Siempre me copiaba a mí.", "Rosi and I were at school together. She always copied from me."),
    N("Vroni envuelve el emmental. Después corta otro trozo, oscuro y duro, de otra rueda, y lo envuelve en papel aparte.",
      "Vroni wraps the Emmental. Then she cuts another piece, dark and hard, from a different wheel, and wraps it separately."),
    Z("—Das ist Bergkäse. Für die Rosi. Ein Geschenk.", "Esto es queso de montaña. Para la Rosi. Un regalo.", "This is mountain cheese. For Rosi. A present."),
    N("Luego saca del delantal una libretita con tapas de plástico, pasa las páginas con el pulgar mojado y copia un número en el borde del papel del queso.",
      "Then she takes a little plastic-covered notebook out of her apron, flicks through the pages with a moistened thumb and copies a number onto the edge of the cheese paper."),
    Z("—Die Nummer vom Kurhotel. Rufen Sie an. Aber laut. Die Rosi hört schlecht.", "El número del hotel del balneario. Llame. Pero alto. La Rosi oye mal.", "The spa hotel's number. Give her a ring. But loudly. Rosi is hard of hearing."),
    Z("—Zusammen mit den Äpfeln acht Euro fünfzig.", "Junto con las manzanas, ocho euros cincuenta.", "With the apples, eight euros fifty altogether."),
    N("Las manzanas eran del puesto de al lado, pero Vroni lo cobra todo. Nadie le lleva la contraria. Marta le da diez euros.",
      "The apples were from the next stall, but Vroni charges for everything. Nobody argues with her. Marta gives her ten euros."),
    Z("—Und hier ist Ihr Wechselgeld. Ein Euro fünfzig.", "Y aquí tiene su cambio. Un euro cincuenta.", "And here's your change. One euro fifty."),
    N("Junto al Maibaum, Marta marca el número. Suena siete veces. Por fin, una voz aguda y muy, muy alta.",
      "Next to the maypole, Marta dials the number. It rings seven times. At last, a high and very, very loud voice."),
    Z("—Ostermeier!", "", ""),
    Z("—Grüß Gott, Frau Ostermeier! Ich heiße Marta Ruiz. Ich wohne in Ihrer Wohnung!", "¡Buenos días, señora Ostermeier! Me llamo Marta Ruiz. ¡Vivo en su piso!", "Good morning, Frau Ostermeier! My name is Marta Ruiz. I live in your flat!"),
    Z("—Ah, die Spanierin! Was brauchen Sie?", "¡Ah, la española! ¿Qué necesita?", "Ah, the Spanish girl! What do you need?"),
    Z("—Ihre Unterschrift. Für die Anmeldung.", "Su firma. Para empadronarme.", "Your signature. For my registration."),
    Z("—Am Telefon unterschreibe ich nichts. Kommen Sie nächsten Samstag. Nach Bad Tölz. Um zwölf.", "Por teléfono no firmo nada. Venga el sábado que viene. A Bad Tölz. A las doce.", "I don't sign anything over the phone. Come next Saturday. To Bad Tölz. At twelve."),
    N("Y cuelga. Sin despedirse. Marta mira a Jonas, que se ríe y le quita una manzana de la bolsa.",
      "And she hangs up. Without saying goodbye. Marta looks at Jonas, who laughs and takes an apple out of her bag."),
    Z("—Willkommen in Bayern. Hier sagt man nicht Tschüss. Hier legt man auf.", "Bienvenida a Baviera. Aquí no se dice adiós. Aquí se cuelga.", "Welcome to Bavaria. Here you don't say goodbye. Here you hang up."),
    Z("Samstag. Bad Tölz. Zwölf Uhr. Und der Bergkäse riecht schon.", "Sábado. Bad Tölz. Las doce. Y el queso de montaña ya huele.", "Saturday. Bad Tölz. Twelve o'clock. And the mountain cheese is already starting to smell.")
  ]),

  // ── Station 4 · WEGBESCHREIBUNG ─────────────────────────────────────
  S('fundament', 4, 'wegbeschreibung', "Die zweite links",
    "El móvil de Marta muere en la Marienplatz. Para encontrar el Bürgerbüro solo le quedan el alemán y los desconocidos.",
    "Marta's phone dies on Marienplatz. To find the Bürgerbüro, all she has left is German and strangers.",
  [
    N("Martes. Marta no tiene clase hasta la tarde y quiere ir al Bürgerbüro a preguntar si su formulario está bien. Aylin le ha dicho: «Pregunta antes. En Alemania, preguntar antes es un deporte nacional.»",
      "Tuesday. Marta has no lectures until the afternoon and wants to go to the Bürgerbüro to ask whether her form is right. Aylin told her: “Ask beforehand. In Germany, asking beforehand is a national sport.”"),
    Z("Marta steigt am Marienplatz aus. Das Handy hat noch drei Prozent.", "Marta se baja en Marienplatz. Al móvil le queda un tres por ciento.", "Marta gets off at Marienplatz. Her phone is down to three per cent."),
    N("Sube las escaleras del metro. Arriba, la plaza: un ayuntamiento neogótico, negro y lleno de torrecitas, como una tarta de cumpleaños de un vampiro. Marta abre el mapa. La pantalla se queda negra.",
      "She climbs the stairs out of the underground. Up top, the square: a neo-Gothic town hall, black and covered in little towers, like a vampire's birthday cake. Marta opens the map. The screen goes black."),
    Z("Null Prozent. Kein Handy. Keine Karte.", "Cero por ciento. Sin móvil. Sin mapa.", "Zero per cent. No phone. No map."),
    Z("Es ist wieder kalt. Ein Mann mit Hut und einer Tüte Brot schaut Marta an.", "Vuelve a hacer frío. Un señor con sombrero y una bolsa de pan mira a Marta.", "It's cold again. A man with a hat and a bag of bread is looking at Marta."),
    N("Un sombrero tirolés, con pluma.",
      "A Tyrolean hat, with a feather."),
    Z("—Kann ich Ihnen helfen?", "¿Puedo ayudarla?", "Can I help you?"),
    Z("—Entschuldigung, wo ist das Bürgerbüro?", "Perdone, ¿dónde está el Bürgerbüro?", "Excuse me, where is the Bürgerbüro?"),
    Z("—Immer geradeaus, dann die zweite links. An der Ecke ist eine Apotheke.", "Todo recto, y luego la segunda a la izquierda. En la esquina hay una farmacia.", "Straight on, then the second on the left. There's a chemist's on the corner."),
    Z("—Ist das weit?", "¿Está lejos?", "Is it far?"),
    Z("—Nein. Fünf Minuten zu Fuß.", "No. Cinco minutos a pie.", "No. Five minutes on foot."),
    N("En ese momento se para una señora con un perro salchicha.",
      "At that moment a woman with a dachshund stops."),
    Z("—Nein, nein. Das ist falsch. Die erste rechts, dann geradeaus bis zur Ampel.", "No, no. Eso está mal. La primera a la derecha y luego todo recto hasta el semáforo.", "No, no. That's wrong. The first on the right, then straight on to the traffic lights."),
    Z("—Die zweite links!", "¡La segunda a la izquierda!", "The second on the left!"),
    Z("—Die erste rechts!", "¡La primera a la derecha!", "The first on the right!"),
    N("Los dos empiezan a discutir. El perro ladra. Ninguno de los tres mira ya a Marta. Ella da las gracias en voz baja y se va. Todo recto. Eso, por lo menos, lo dicen los dos.",
      "The two of them start arguing. The dog barks. None of the three is looking at Marta any more. She says thank you quietly and leaves. Straight on. That, at least, they both agree on."),
    Z("Marta geht geradeaus. Dann die zweite links. An der Ecke ist eine Apotheke.", "Marta va todo recto. Luego la segunda a la izquierda. En la esquina hay una farmacia.", "Marta goes straight on. Then the second on the left. There's a chemist's on the corner."),
    N("El señor del sombrero tenía razón. Marta decide fiarse siempre de los hombres con pan.",
      "The man in the hat was right. Marta decides always to trust men carrying bread."),
    Z("BÜRGERBÜRO · INFORMATION · BITTE NUMMER ZIEHEN", "BÜRGERBÜRO · INFORMACIÓN · POR FAVOR, COJA NÚMERO", "BÜRGERBÜRO · INFORMATION · PLEASE TAKE A NUMBER"),
    N("En el mostrador de información hay un funcionario joven con un jersey de punto y una taza que dice «Montag kann weg». Marta saca su formulario.",
      "At the information desk sits a young official in a knitted jumper with a mug that says “Montag kann weg” — Monday can go. Marta takes out her form."),
    Z("—Guten Tag. Ich habe am vierundzwanzigsten einen Termin. Ist das Formular richtig?", "Buenos días. Tengo cita el veinticuatro. ¿Está bien el formulario?", "Good morning. I've got an appointment on the twenty-fourth. Is the form right?"),
    Z("—Ja, das Formular ist richtig. Und haben Sie die Wohnungsgeberbestätigung?", "Sí, el formulario está bien. ¿Y tiene la confirmación de la casera?", "Yes, the form is right. And have you got the landlord's confirmation?"),
    Z("—Noch nicht. Am Samstag.", "Todavía no. El sábado.", "Not yet. On Saturday."),
    Z("—Wichtig: mit Unterschrift. Von der Vermieterin. Nicht von Ihnen. Und keine Kopie. Das Original.", "Importante: con firma. De la casera. No de usted. Y nada de copias. El original.", "Important: with a signature. From the landlady. Not from you. And no copy. The original."),
    N("Lo dice como quien ya ha visto de todo: firmas de compañeros de piso, firmas de madres, una vez incluso la firma de un gato.",
      "He says it like someone who has seen it all: signatures from flatmates, signatures from mothers, once even a cat's signature."),
    Z("—Danke. Und wo ist die Marienplatz?", "Gracias. ¿Y dónde está la Marienplatz?", "Thank you. And where is Marienplatz?"),
    Z("—Der Marienplatz. Rechts, dann immer geradeaus. Sie hören ihn schon.", "El Marienplatz. A la derecha y luego todo recto. Ya lo oirá.", "Marienplatz. Right, then straight on. You'll hear it."),
    N("«Der», no «die». Hasta las plazas tienen género aquí, y nunca el que una espera. Marta sale. Las campanas empiezan a sonar.",
      "“Der”, not “die”. Even the squares have a gender here, and never the one you'd expect. Marta goes out. Bells begin to ring."),
    Z("Es ist elf Uhr. Am Rathaus tanzen kleine Figuren. Alle Leute schauen nach oben.", "Son las once. En el ayuntamiento bailan unas figuritas. Toda la gente mira hacia arriba.", "It's eleven o'clock. Little figures are dancing on the town hall. Everyone is looking up."),
    N("Es el Glockenspiel: caballeros, toneleros, un torneo de juguete. Cientos de turistas con el móvil en alto. Marta no puede grabar nada. Así que lo mira de verdad. Al final, un gallito dorado canta tres veces.",
      "It's the Glockenspiel: knights, coopers, a toy tournament. Hundreds of tourists holding their phones up. Marta can't film anything. So she actually watches it. At the end, a little golden cockerel crows three times."),
    N("Y entonces se da cuenta: ha vuelto sola. Sin mapa. Con cuatro palabras.",
      "And then she realises: she has found her way back on her own. Without a map. With four words."),
    Z("Geradeaus. Links. Rechts. Ecke.", "Recto. Izquierda. Derecha. Esquina.", "Straight on. Left. Right. Corner.")
  ]),

  // ── Station 5 · BAHNHOF ─────────────────────────────────────────────
  S('fundament', 5, 'bahnhof', "Hin und zurück",
    "La máquina de billetes hace demasiadas preguntas, la taquillera solo una que Marta no entiende — y el tren sale a su hora.",
    "The ticket machine asks too many questions, the ticket clerk only one that Marta doesn't understand — and the train leaves on time.",
  [
    Z("Samstag, halb neun. Marta ist am Hauptbahnhof. Sie hat den Pass, das Formular und den Bergkäse.", "Sábado, las ocho y media. Marta está en la estación central. Lleva el pasaporte, el formulario y el queso de montaña.", "Saturday, half past eight. Marta is at the main station. She has her passport, the form and the mountain cheese."),
    N("El queso de Vroni va envuelto en dos bolsas. Aun así, huele.",
      "Vroni's cheese is wrapped in two bags. It still smells."),
    Z("Der Hauptbahnhof ist groß und laut. Es gibt viele Gleise und viele Automaten.", "La estación central es grande y ruidosa. Hay muchas vías y muchas máquinas.", "The main station is big and noisy. There are lots of platforms and lots of machines."),
    Z("Marta steht vor einem roten Automaten. Der Automat hat viele Fragen.", "Marta está delante de una máquina roja. La máquina tiene muchas preguntas.", "Marta is standing in front of a red machine. The machine has a lot of questions."),
    N("Adónde va. Desde dónde. Cuándo. Si viaja con bici, con perro, con niños, en primera o en segunda. A los cuatro minutos, la máquina le pregunta si sigue ahí. Marta le dice que no y se va a la taquilla.",
      "Where she is going. Where from. When. Whether she is travelling with a bike, a dog, children, first or second class. After four minutes, the machine asks whether she is still there. Marta tells it no and goes to the ticket office."),
    Z("Marta geht zum Schalter. Am Schalter sitzt eine Frau.", "Marta va a la taquilla. En la taquilla hay una mujer.", "Marta goes to the ticket office. A woman is sitting at the counter."),
    Z("—Guten Tag. Bitte sehr?", "Buenos días. ¿Dígame?", "Good morning. How can I help?"),
    Z("—Eine Fahrkarte nach Bad Tölz, bitte.", "Un billete para Bad Tölz, por favor.", "A ticket to Bad Tölz, please."),
    Z("—Einfach oder hin und zurück?", "¿Solo ida o ida y vuelta?", "Single or return?"),
    Z("—Hin und zurück.", "Ida y vuelta.", "Return."),
    Z("—Haben Sie eine Bahncard?", "¿Tiene usted una Bahncard?", "Have you got a Bahncard?"),
    Z("—Eine was?", "¿Una qué?", "A what?"),
    Z("—Also nein.", "O sea, que no.", "So that's a no."),
    N("La taquillera no sonríe, pero tampoco suspira. En Alemania, piensa Marta, eso ya es una forma de cariño.",
      "The clerk doesn't smile, but she doesn't sigh either. In Germany, Marta thinks, that already counts as a kind of affection."),
    Z("—Wann fährt der Zug?", "¿A qué hora sale el tren?", "When does the train leave?"),
    Z("—Der nächste um neun Uhr zwölf.", "El próximo, a las nueve y doce.", "The next one at twelve minutes past nine."),
    Z("—Und von welchem Gleis?", "¿Y de qué vía?", "And from which platform?"),
    Z("—Gleis dreißig. Ganz hinten links.", "Vía treinta. Al fondo a la izquierda.", "Platform thirty. Right at the back on the left."),
    N("Aylin le ha advertido: «Los trenes alemanes son puntuales solo en las películas. En la vida real, llévate un libro.» Marta lleva un libro. Y una manzana. Y el queso.",
      "Aylin warned her: “German trains are only punctual in films. In real life, take a book.” Marta has a book. And an apple. And the cheese."),
    Z("Es ist neun Uhr elf. Der Zug steht am Gleis. Die Türen sind offen.", "Son las nueve y once. El tren está en la vía. Las puertas están abiertas.", "It's eleven minutes past nine. The train is at the platform. The doors are open."),
    Z("Es ist neun Uhr zwölf. Die Türen schließen. Der Zug fährt ab.", "Son las nueve y doce. Las puertas se cierran. El tren sale.", "It's twelve minutes past nine. The doors close. The train leaves."),
    N("Exactamente. Marta le escribe a Aylin: «¡¡Puntual!!» La respuesta llega en diez segundos: «Glück gehabt. Kauf ein Los.» Has tenido suerte. Cómprate un décimo.",
      "Exactly. Marta texts Aylin: “On time!!” The reply comes within ten seconds: “Glück gehabt. Kauf ein Los.” Lucky you. Buy a lottery ticket."),
    N("Enfrente se sienta un señor con bigote y una revista de caza. Al cabo de diez minutos, olfatea el aire. Mira a Marta. Mira la bolsa.",
      "A man with a moustache and a hunting magazine sits opposite her. After ten minutes he sniffs the air. He looks at Marta. He looks at the bag."),
    Z("—Bergkäse?", "¿Queso de montaña?", "Mountain cheese?"),
    Z("—Ja. Ein Geschenk.", "Sí. Es un regalo.", "Yes. It's a present."),
    Z("—Ein gutes Geschenk.", "Un buen regalo.", "A good present."),
    N("Y vuelve a su revista. Por lo visto, en Baviera el queso apestoso es algo que se respeta.",
      "And he goes back to his magazine. In Bavaria, it seems, smelly cheese is something to be respected."),
    Z("Nach Holzkirchen kommen Wiesen, Kühe und kleine Kirchen. Und dann sieht Marta die Berge.", "Después de Holzkirchen vienen prados, vacas e iglesias pequeñas. Y entonces Marta ve las montañas.", "After Holzkirchen come meadows, cows and little churches. And then Marta sees the mountains."),
    N("Los Alpes. Grises, enormes, con nieve arriba, como azúcar glas. Marta pega la frente al cristal. En Sevilla, la montaña más alta que ve desde casa es la Giralda.",
      "The Alps. Grey, enormous, with snow on top like icing sugar. Marta presses her forehead to the glass. In Seville, the highest mountain she can see from home is the Giralda."),
    Z("—Das sind die Alpen. Schön, oder?", "Son los Alpes. Bonitos, ¿eh?", "Those are the Alps. Beautiful, aren't they?"),
    Z("—Sehr schön. Und sehr kalt.", "Muy bonitos. Y muy fríos.", "Very beautiful. And very cold."),
    Z("—Ach was. Heute ist es warm.", "Qué va. Hoy hace calor.", "Nonsense. It's warm today."),
    N("Fuera, según la pantalla del vagón, hace ocho grados.",
      "Outside, according to the screen in the carriage, it is eight degrees."),
    Z("Um zehn Uhr fünfzehn kommt der Zug in Bad Tölz an. Pünktlich.", "A las diez y cuarto, el tren llega a Bad Tölz. Puntual.", "At quarter past ten the train arrives in Bad Tölz. On time.")
  ]),

  // ── Station 6 · RESTAURANT ──────────────────────────────────────────
  S('fundament', 6, 'restaurant', "Haben Sie reserviert?",
    "Comida con la señora Ostermeier: un asado, una prueba, un viaje de novios a Sevilla en 1968 — y un bolígrafo verde.",
    "Lunch with Frau Ostermeier: a roast, a test, a honeymoon in Seville in 1968 — and a green pen.",
  [
    Z("Um fünf vor zwölf steht Marta vor dem Gasthaus. Sie ist fünf Minuten zu früh. Sie ist sehr stolz.", "A las doce menos cinco, Marta está delante de la fonda. Llega cinco minutos antes. Está muy orgullosa.", "At five to twelve, Marta is standing outside the inn. She is five minutes early. She is very proud of herself."),
    N("Fachada blanca, flores en las ventanas, un ciervo pintado sobre la puerta.",
      "White façade, flowers in the windows, a stag painted above the door."),
    N("La señora Ostermeier ya está dentro. Desde las once y media.",
      "Frau Ostermeier is already inside. Since half past eleven."),
    Z("Ein Kellner mit Lederhose kommt an die Tür.", "Un camarero con pantalones de cuero viene a la puerta.", "A waiter in lederhosen comes to the door."),
    Z("—Grüß Gott. Haben Sie reserviert?", "Buenos días. ¿Tiene reserva?", "Good afternoon. Have you got a reservation?"),
    Z("—Ja. Auf den Namen Ostermeier.", "Sí. A nombre de Ostermeier.", "Yes. Under the name Ostermeier."),
    Z("—Ah, die Frau Ostermeier. Der Tisch am Fenster.", "Ah, la señora Ostermeier. La mesa junto a la ventana.", "Ah, Frau Ostermeier. The table by the window."),
    N("Junto a la ventana hay una señora diminuta con el pelo blanco cardado, una chaqueta de lana verde y unos ojos azules muy despiertos. Rosa Ostermeier. Ochenta y un años. Mira a Marta de arriba abajo, sin prisa.",
      "By the window sits a tiny woman with white backcombed hair, a green wool jacket and very alert blue eyes. Rosa Ostermeier. Eighty-one. She looks Marta up and down, taking her time."),
    Z("—Sie sind die Spanierin. Setzen Sie sich. Sie sind zu dünn.", "Usted es la española. Siéntese. Está demasiado delgada.", "You're the Spanish girl. Sit down. You're too thin."),
    Z("—Möchten Sie schon bestellen?", "¿Quieren pedir ya?", "Would you like to order?"),
    Z("—Was können Sie empfehlen?", "¿Qué nos recomienda?", "What can you recommend?"),
    Z("—Heute ist der Schweinebraten sehr gut. Mit Knödel und Krautsalat als Beilage.", "Hoy el asado de cerdo está muy bueno. Con albóndiga de pan y ensalada de col de guarnición.", "The roast pork is very good today. With a dumpling and coleslaw on the side."),
    Z("—Dann nehme ich den Schweinebraten.", "Entonces tomaré el asado de cerdo.", "Then I'll have the roast pork."),
    Z("—Ich auch. Und ein Radler.", "Yo también. Y una clara.", "Me too. And a shandy."),
    Z("—Und für das Fräulein?", "¿Y para la señorita?", "And for the young lady?"),
    Z("—Ein Wasser, bitte.", "Un agua, por favor.", "A water, please."),
    N("La señora Ostermeier la mira como si hubiera pedido un vaso de aire. Luego junta las manos sobre la mesa, como un juez. Empieza la prueba.",
      "Frau Ostermeier looks at her as if she had ordered a glass of air. Then she folds her hands on the table, like a judge. The test begins."),
    Z("—Warum München?", "¿Por qué Múnich?", "Why Munich?"),
    Z("—Ich studiere Umweltwissenschaften. Die TU ist sehr gut.", "Estudio Ciencias Ambientales. La TU es muy buena.", "I study environmental sciences. The TU is very good."),
    Z("—Und warum brauchen Sie meine Unterschrift?", "¿Y por qué necesita mi firma?", "And why do you need my signature?"),
    Z("—Für die Anmeldung. Ohne Anmeldung kein Geld.", "Para empadronarme. Sin padrón, no hay sueldo.", "For my registration. No registration, no money."),
    N("Es la verdad. No suena bonita. Pero la señora Ostermeier asiente, como si la verdad fuera el plato que esperaba.",
      "It's the truth. It doesn't sound pretty. But Frau Ostermeier nods, as if the truth were the dish she was waiting for."),
    Z("Der Schweinebraten kommt. Er ist groß und knusprig. Der Knödel ist so groß wie eine Faust.", "Llega el asado. Es grande y crujiente. La bola de pan es tan grande como un puño.", "The roast pork arrives. It's big and crispy. The dumpling is as big as a fist."),
    Z("—Schmeckt's?", "¿Está bueno?", "Is it good?"),
    Z("—Sehr lecker.", "Buenísimo.", "Delicious."),
    Z("—Woher in Spanien?", "¿De qué parte de España?", "Where in Spain?"),
    Z("—Aus Sevilla.", "De Sevilla.", "From Seville."),
    N("El tenedor de la señora Ostermeier se queda quieto. Por primera vez, sonríe.",
      "Frau Ostermeier's fork goes still. For the first time, she smiles."),
    Z("—Sevilla! Neunzehnhundertachtundsechzig. Meine Hochzeitsreise. Mit meinem Hans.", "¡Sevilla! Mil novecientos sesenta y ocho. Mi viaje de novios. Con mi Hans.", "Seville! Nineteen sixty-eight. My honeymoon. With my Hans."),
    Z("—Und? Wie war es?", "¿Y? ¿Qué tal?", "And? How was it?"),
    Z("—Heiß. So heiß! Der Hans war jeden Tag rot wie eine Tomate.", "Calor. ¡Muchísimo calor! Hans estaba todos los días rojo como un tomate.", "Hot. So hot! Hans was red as a tomato every day."),
    N("Y de pronto, en un castellano oxidado, con una erre bávara que rueda como una carreta: «¡Qué calor!» Las dos se ríen tan fuerte que el camarero se vuelve.",
      "And suddenly, in rusty Spanish, with a Bavarian r that rolls like a cart: “¡Qué calor!” The two of them laugh so loudly that the waiter turns round."),
    N("Marta saca el queso. La señora Ostermeier lo huele y cierra los ojos.",
      "Marta takes out the cheese. Frau Ostermeier smells it and closes her eyes."),
    Z("—Von der Vroni? Die Vroni hat in der Schule immer bei mir abgeschrieben!", "¿De la Vroni? ¡La Vroni siempre me copiaba a mí en el colegio!", "From Vroni? Vroni always copied from me at school!"),
    N("Marta no dice nada. Algunas guerras tienen setenta años y es mejor no tocarlas. Pone el formulario sobre el mantel. La señora Ostermeier saca de su bolso un bolígrafo verde.",
      "Marta says nothing. Some wars are seventy years old and best left alone. She puts the form on the tablecloth. Frau Ostermeier takes a green pen out of her handbag."),
    Z("—Grün. Ich unterschreibe immer grün. Blau ist für Beamte.", "Verde. Yo siempre firmo en verde. El azul es para los funcionarios.", "Green. I always sign in green. Blue is for civil servants."),
    Z("Sie unterschreibt langsam: Rosa Ostermeier.", "Firma despacio: Rosa Ostermeier.", "She signs slowly: Rosa Ostermeier."),
    Z("—Und jetzt einen Nachtisch. Apfelstrudel. Zwei.", "Y ahora, un postre. Strudel de manzana. Dos.", "And now a dessert. Apple strudel. Two."),
    Z("—Ich bin satt, Frau Ostermeier.", "Estoy llena, señora Ostermeier.", "I'm full, Frau Ostermeier."),
    Z("—Sie sind zu dünn. Zwei Apfelstrudel!", "Está demasiado delgada. ¡Dos strudel de manzana!", "You're too thin. Two apple strudels!"),
    N("Al final, Marta busca la cartera. La señora Ostermeier le pone la mano encima: una mano pequeña, seca y sorprendentemente fuerte.",
      "At the end, Marta reaches for her purse. Frau Ostermeier puts her hand on it: a small, dry, surprisingly strong hand."),
    Z("—Passt schon. Sie sind mein Gast.", "Deje, deje. Es usted mi invitada.", "It's fine. You're my guest."),
    N("En el tren de vuelta, Marta lleva la carpeta sobre las rodillas como si fuera una tarta. Una firma verde. Veinticuatro letras con firma.",
      "On the train back, Marta holds the folder on her knees as if it were a cake. A green signature. Twenty-four letters, signed."),
    Z("Ich habe die Unterschrift.", "Tengo la firma.", "I've got the signature.")
  ]),

  // ── Station 7 · WETTER ──────────────────────────────────────────────
  S('fundament', 7, 'wetter', "Morgen regnet es",
    "Veintidós grados en octubre y los Alpes al final de la calle. El barómetro del señor Brandl no está de acuerdo.",
    "Twenty-two degrees in October and the Alps at the end of the street. Herr Brandl's barometer disagrees.",
  [
    Z("Am Montag macht Marta um sieben das Fenster auf. Die Luft ist mild und trocken.", "El lunes, Marta abre la ventana a las siete. El aire es suave y seco.", "On Monday, Marta opens the window at seven. The air is mild and dry."),
    Z("Die Sonne scheint. Es ist warm. Es sind zweiundzwanzig Grad.", "Hace sol. Hace calor. Hay veintidós grados.", "The sun is shining. It's warm. It's twenty-two degrees."),
    N("Casi andaluz. Por primera vez desde que llegó, Marta se pone una camiseta. Solo una. Le parece un acto revolucionario.",
      "Almost Andalusian. For the first time since she arrived, Marta puts on a T-shirt. Just one. It feels like a revolutionary act."),
    Z("Unten in der Bäckerei hat Frau Schmid die Hand an der Stirn.", "Abajo, en la panadería, la señora Schmid tiene la mano en la frente.", "Downstairs in the bakery, Frau Schmid has her hand on her forehead."),
    Z("—Ich habe Kopfschmerzen. Das ist der Föhn.", "Me duele la cabeza. Es el Föhn.", "I've got a headache. It's the Föhn."),
    Z("—Was ist der Föhn?", "¿Qué es el Föhn?", "What's the Föhn?"),
    Z("—Ein warmer Wind aus den Bergen. Er macht Kopfschmerzen.", "Un viento cálido que viene de las montañas. Da dolor de cabeza.", "A warm wind from the mountains. It gives you headaches."),
    N("Aylin, que pasa por detrás con su café, le susurra a Marta: «El Föhn es la excusa bávara para todo. Dolor de cabeza, mal humor, un divorcio. Todo es culpa del Föhn.»",
      "Aylin, passing behind with her coffee, whispers to Marta: “The Föhn is the Bavarian excuse for everything. Headaches, bad moods, a divorce. Everything is the Föhn's fault.”"),
    Z("Am Nachmittag geht Marta mit Jonas an der Isar spazieren. Viele Leute sitzen in der Sonne, im T-Shirt.", "Por la tarde, Marta pasea con Jonas a orillas del Isar. Mucha gente está sentada al sol, en camiseta.", "In the afternoon, Marta goes for a walk along the Isar with Jonas. Lots of people are sitting in the sun in T-shirts."),
    N("Como en julio. Y al fondo, detrás de los tejados, donde normalmente solo hay nubes, aparece algo.",
      "As if it were July. And in the distance, behind the rooftops, where normally there are only clouds, something appears."),
    Z("—Sind das die Alpen? Hier, in München?", "¿Son los Alpes? ¿Aquí, en Múnich?", "Are those the Alps? Here, in Munich?"),
    Z("—Ja. Bei Föhn sieht man die Berge. Sie sind ganz nah.", "Sí. Con Föhn se ven las montañas. Parecen muy cerca.", "Yes. When there's Föhn you can see the mountains. They look very close."),
    Z("—Was für ein schöner Tag!", "¡Qué día tan bonito!", "What a beautiful day!"),
    Z("—Heute, ja. Aber morgen regnet es, glaube ich.", "Hoy sí. Pero mañana llueve, creo.", "Today, yes. But it'll rain tomorrow, I think."),
    Z("—Regen? Es gibt keine einzige Wolke!", "¿Lluvia? ¡No hay ni una nube!", "Rain? There isn't a single cloud!"),
    Z("Im Treppenhaus steht Herr Brandl, der Nachbar aus dem dritten Stock. Er klopft an ein altes Barometer.", "En la escalera está el señor Brandl, el vecino del tercero. Da golpecitos a un barómetro antiguo.", "Herr Brandl, the neighbour from the third floor, is standing on the stairs. He is tapping an old barometer."),
    N("Toc, toc. Es jubilado y lleva corbata, también los lunes.",
      "Tap, tap. He is retired and wears a tie, Mondays included."),
    Z("—Guten Abend, Herr Brandl.", "Buenas tardes, señor Brandl.", "Good evening, Herr Brandl."),
    Z("—Guten Abend. Das Barometer fällt. Morgen regnet es. Und Wind.", "Buenas tardes. El barómetro baja. Mañana llueve. Y viento.", "Good evening. The barometer is falling. Tomorrow it'll rain. And wind."),
    Z("—Aber die Sonne scheint! Es ist so warm!", "¡Pero hace sol! ¡Hace tanto calor!", "But the sun is shining! It's so warm!"),
    Z("—Der Föhn lügt. Das Barometer lügt nie. Haben Sie einen Schirm?", "El Föhn miente. El barómetro no miente nunca. ¿Tiene paraguas?", "The Föhn lies. The barometer never lies. Have you got an umbrella?"),
    Z("—Nein. Ich brauche keinen Schirm.", "No. No necesito paraguas.", "No. I don't need an umbrella."),
    N("El señor Brandl la mira como se mira a alguien que va a cruzar en rojo. Luego vuelve a dar golpecitos al barómetro.",
      "Herr Brandl looks at her the way you look at someone about to cross on red. Then he goes back to tapping the barometer."),
    Z("Am nächsten Morgen ist der Himmel grau. Es ist kalt. Es sind acht Grad.", "A la mañana siguiente, el cielo está gris. Hace frío. Hay ocho grados.", "The next morning, the sky is grey. It's cold. It's eight degrees."),
    Z("Um zwölf kommt der Wind. Um eins kommt der Regen.", "A las doce llega el viento. A la una, la lluvia.", "At twelve the wind comes. At one, the rain."),
    N("No es lluvia de Sevilla, que cae dos veces al año y la gente sale a mirarla. Es lluvia de lado, fría, que se mete por el cuello. Marta lleva la chaqueta vaquera. Doce minutos hasta el tranvía.",
      "It isn't Seville rain, which falls twice a year and people go outside to watch. It's sideways rain, cold, getting down the back of your neck. Marta is wearing her denim jacket. Twelve minutes to the tram."),
    Z("Marta ist nass. Ganz nass. Die Schuhe, die Jacke, die Haare.", "Marta está mojada. Empapada. Los zapatos, la chaqueta, el pelo.", "Marta is wet. Soaked. Her shoes, her jacket, her hair."),
    N("En la parada llega un tranvía. Se abre la puerta. Al volante, Jonas. Le tiende un paraguas enorme, de plástico azul y blanco, con el logo de la compañía de transportes. El paraguas más feo de Baviera.",
      "At the stop, a tram arrives. The door opens. At the controls: Jonas. He holds out a huge umbrella, blue and white plastic, with the transport company's logo. The ugliest umbrella in Bavaria."),
    Z("—Hier! Nimm den Schirm mit!", "¡Toma! ¡Llévate el paraguas!", "Here! Take the umbrella!"),
    Z("—Danke, Jonas. Aber jetzt ist es zu spät.", "Gracias, Jonas. Pero ahora ya es tarde.", "Thanks, Jonas. But it's too late now."),
    N("Lo abre de todos modos. El viento le da la vuelta en dos segundos. Los pasajeros del tranvía aplauden.",
      "She opens it anyway. The wind turns it inside out in two seconds. The passengers on the tram applaud."),
    N("En casa, en la escalera, se abre una puerta un piso más arriba. Claro.",
      "At home, on the stairs, a door opens one floor up. Of course."),
    Z("—Das Barometer lügt nie.", "El barómetro no miente nunca.", "The barometer never lies."),
    N("Esa noche, Marta estornuda. Una vez. Dos. Nueve. La cita es el jueves.",
      "That night, Marta sneezes. Once. Twice. Nine times. The appointment is on Thursday."),
    Z("Morgen nehme ich den Schirm mit. Den hässlichen.", "Mañana me llevo el paraguas. El feo.", "Tomorrow I'll take the umbrella. The ugly one.")
  ]),

  // ── Station 8 · ARZT ────────────────────────────────────────────────
  S('fundament', 8, 'arzt', "Seit gestern",
    "Fiebre, dolor de cabeza, una tarjeta azul de Sevilla — y una médica que da tres días de baja a alguien que tiene cita mañana.",
    "Fever, a headache, a blue card from Seville — and a doctor who signs someone off for three days when she has an appointment tomorrow.",
  [
    Z("Mittwoch, sieben Uhr. Marta liegt im Bett. Der Kopf ist schwer und heiß.", "Miércoles, las siete. Marta está en la cama. La cabeza le pesa y le arde.", "Wednesday, seven o'clock. Marta is lying in bed. Her head is heavy and hot."),
    N("Aylin entra sin llamar y le pone un termómetro en la boca. Se nota que estudia Medicina.",
      "Aylin comes in without knocking and puts a thermometer in her mouth. You can tell she studies medicine."),
    Z("—Achtunddreißig Komma fünf. Du gehst zur Ärztin. Heute.", "Treinta y ocho coma cinco. Vas a la médica. Hoy.", "Thirty-eight point five. You're going to the doctor. Today."),
    Z("—Ist das der Föhn?", "¿Es el Föhn?", "Is it the Föhn?"),
    Z("—Nein. Das ist der Regen. Und die Jacke.", "No. Es la lluvia. Y la chaqueta.", "No. It's the rain. And the jacket."),
    Z("Die Praxis von Frau Doktor Lindner ist nicht weit. Im Wartezimmer sitzen sechs Leute. Niemand spricht.", "La consulta de la doctora Lindner no está lejos. En la sala de espera hay seis personas. Nadie habla.", "Dr Lindner's surgery isn't far. Six people are sitting in the waiting room. Nobody is talking."),
    N("Un silencio de biblioteca. Una señora tose y pide perdón a todos.",
      "The silence of a library. A woman coughs and apologises to everyone."),
    Z("—Guten Morgen. Haben Sie einen Termin?", "Buenos días. ¿Tiene cita?", "Good morning. Have you got an appointment?"),
    Z("—Nein. Ich habe Fieber.", "No. Tengo fiebre.", "No. I've got a temperature."),
    Z("—Ihre Versichertenkarte, bitte.", "Su tarjeta sanitaria, por favor.", "Your health insurance card, please."),
    N("Marta le da la tarjeta sanitaria europea, la azul, la que su madre le metió en la cartera en el aeropuerto de Sevilla «por si acaso». La recepcionista la mira por delante y por detrás.",
      "Marta hands over her European health insurance card, the blue one her mother put in her wallet at Seville airport “just in case”. The receptionist looks at the front and the back."),
    Z("—Aus Spanien. Gut. Bitte nehmen Sie Platz.", "De España. Bien. Siéntese, por favor.", "From Spain. Fine. Please take a seat."),
    Z("Nach vierzig Minuten ruft die Ärztin: »Frau Ruiz?«", "Después de cuarenta minutos, la médica llama: «¿Señora Ruiz?»", "After forty minutes, the doctor calls: “Frau Ruiz?”"),
    Z("Die Ärztin ist groß. Sie trägt Turnschuhe in Orange.", "La médica es alta. Lleva zapatillas de deporte naranjas.", "The doctor is tall. She is wearing orange trainers."),
    N("No pegan con nada. Habla despacio, como si supiera que el alemán con fiebre es más difícil.",
      "They don't go with anything. She speaks slowly, as if she knows that German with a temperature is harder."),
    Z("—Guten Tag. Was führt Sie zu mir?", "Buenos días. ¿Qué la trae por aquí?", "Hello. What brings you to see me?"),
    Z("—Ich habe Kopfschmerzen.", "Me duele la cabeza.", "I've got a headache."),
    Z("—Seit wann denn?", "¿Desde cuándo?", "Since when?"),
    Z("—Seit gestern. Und ich habe Fieber. Und ich bin sehr müde.", "Desde ayer. Y tengo fiebre. Y estoy muy cansada.", "Since yesterday. And I've got a temperature. And I'm very tired."),
    Z("—Husten Sie?", "¿Tiene tos?", "Have you got a cough?"),
    Z("—Ein bisschen. Ist das der Föhn?", "Un poco. ¿Es el Föhn?", "A little. Is it the Föhn?"),
    N("La doctora se ríe por primera vez. Una risa corta.",
      "The doctor laughs for the first time. A short laugh."),
    Z("—Sie sind erst zwei Wochen hier und sagen schon »Föhn«? Nein. Das ist eine Erkältung.", "¿Lleva solo dos semanas aquí y ya dice «Föhn»? No. Es un resfriado.", "You've only been here two weeks and you're already saying “Föhn”? No. It's a cold."),
    N("Le mira la garganta, le escucha los pulmones, le pregunta si estudia o trabaja. Marta dice que las dos cosas. La doctora escribe algo en el ordenador.",
      "She looks at her throat, listens to her lungs, asks whether she studies or works. Marta says both. The doctor types something into the computer."),
    Z("—Nehmen Sie eine Tablette am Morgen und eine am Abend. Hier ist das Rezept. Und ich schreibe Sie für drei Tage krank.", "Tome una pastilla por la mañana y otra por la noche. Aquí tiene la receta. Y le doy la baja para tres días.", "Take one tablet in the morning and one in the evening. Here's the prescription. And I'm signing you off for three days."),
    Z("—Drei Tage? Aber morgen habe ich einen Termin! Im Bürgerbüro. Um acht Uhr fünfzehn.", "¿Tres días? ¡Pero mañana tengo una cita! En el Bürgerbüro. A las ocho y cuarto.", "Three days? But I've got an appointment tomorrow! At the Bürgerbüro. At quarter past eight."),
    Z("—Für die Anmeldung?", "¿Para empadronarse?", "For your registration?"),
    Z("—Ja.", "Sí.", "Yes."),
    N("La doctora se quita las gafas. Es de Múnich. Sabe lo que cuesta una cita en el Bürgerbüro. Hay cosas más difíciles de conseguir que la salud.",
      "The doctor takes off her glasses. She is from Munich. She knows what an appointment at the Bürgerbüro costs. Some things are harder to come by than good health."),
    Z("—Wie lange dauert der Termin?", "¿Cuánto dura la cita?", "How long is the appointment?"),
    Z("—Zehn Minuten, glaube ich.", "Diez minutos, creo.", "Ten minutes, I think."),
    Z("—Dann gehen Sie hin. Mit Schal. Und danach ins Bett.", "Entonces vaya. Con bufanda. Y después, a la cama.", "Then go. With a scarf. And straight to bed afterwards."),
    Z("Marta geht in die Apotheke an der Ecke. Sie gibt der Apothekerin das Rezept.", "Marta va a la farmacia de la esquina. Le da la receta a la farmacéutica.", "Marta goes to the chemist's on the corner. She gives the pharmacist the prescription."),
    N("Rezept. Le hace gracia: en alemán, como en español, la misma palabra sirve para la medicina y para el bizcocho. Por una vez, los dos idiomas están de acuerdo.",
      "Rezept. It amuses her: in German, as in Spanish, the same word works for medicine and for sponge cake. For once, the two languages agree."),
    Z("—Hier sind Ihre Tabletten. Gute Besserung!", "Aquí tiene sus pastillas. ¡Que se mejore!", "Here are your tablets. Get well soon!"),
    Z("—Danke.", "Gracias.", "Thank you."),
    N("Gute Besserung: «buena mejoría». A Marta le gusta. No promete que mañana estarás bien, solo un poco mejor. Realista y amable a la vez. Muy alemán.",
      "Gute Besserung: “good improvement”. Marta likes it. It doesn't promise you'll be well tomorrow, only a bit better. Realistic and kind at the same time. Very German."),
    Z("Morgen um acht Uhr fünfzehn. Mit Schal. Danach ins Bett.", "Mañana a las ocho y cuarto. Con bufanda. Después, a la cama.", "Tomorrow at quarter past eight. With a scarf. Then bed.")
  ]),

  // ── Station 9 · HOTEL ───────────────────────────────────────────────
  S('fundament', 9, 'hotel', "Auf den Namen Ruiz",
    "A la una de la madrugada, el techo del baño empieza a llover. Marta salva primero un papel — y deletrea su apellido a un portero de noche.",
    "At one in the morning, the bathroom ceiling starts to rain. Marta saves a piece of paper first — and spells her surname for a night porter.",
  [
    Z("Mittwochnacht, ein Uhr zehn. Marta hört ein Geräusch. Es kommt aus dem Bad.", "Miércoles por la noche, la una y diez. Marta oye un ruido. Viene del baño.", "Wednesday night, ten past one. Marta hears a noise. It's coming from the bathroom."),
    N("Plic. Plic. Plic. Un ruido nuevo.",
      "Drip. Drip. Drip. A new sound."),
    Z("Im Bad ist Wasser. Viel Wasser. Es kommt von oben, aus der Decke.", "En el baño hay agua. Mucha agua. Viene de arriba, del techo.", "There's water in the bathroom. Lots of water. It's coming from above, from the ceiling."),
    N("Arriba viven los Huber, que ponen la lavadora de noche porque la luz es más barata. Su lavadora, por lo visto, ha decidido mudarse abajo.",
      "The Hubers live upstairs; they run their washing machine at night because electricity is cheaper. Their washing machine, apparently, has decided to move downstairs."),
    Z("—Aylin! Jonas! Wasser!", "¡Aylin! ¡Jonas! ¡Agua!", "Aylin! Jonas! Water!"),
    Z("Jonas läuft nach oben zu den Hubers. Aylin bringt alle Handtücher.", "Jonas sube corriendo a casa de los Huber. Aylin trae todas las toallas.", "Jonas runs upstairs to the Hubers. Aylin brings all the towels."),
    N("Y Marta, con fiebre, en pijama y descalza en el agua, hace algo que la sorprende a ella misma.",
      "And Marta, feverish, in pyjamas and barefoot in the water, does something that surprises even her."),
    N("No coge el móvil. No coge el portátil. Coge una funda de plástico transparente de su escritorio. Dentro, el formulario y una firma verde.",
      "She doesn't grab her phone. She doesn't grab her laptop. She grabs a clear plastic sleeve from her desk. Inside: the form and a green signature."),
    Z("—Die Wohnungsgeberbestätigung ist trocken!", "¡La confirmación de la casera está seca!", "The landlord's confirmation is dry!"),
    Z("—Siehst du? Wichtige Papiere immer in eine Klarsichthülle. Jetzt bist du Deutsche.", "¿Ves? Los papeles importantes, siempre en una funda de plástico. Ya eres alemana.", "See? Important papers always go in a plastic sleeve. Now you're German."),
    Z("Um zwei kommt ein Mann von der Hausverwaltung. Er schaut die Decke an. Dann schaut er Marta an.", "A las dos llega un hombre de la administración de la finca. Mira el techo. Luego mira a Marta.", "At two, a man from the property management arrives. He looks at the ceiling. Then he looks at Marta."),
    Z("—Hier können Sie nicht schlafen. Zwei Nächte. Wir bezahlen eine Pension.", "Aquí no puede dormir. Dos noches. Nosotros pagamos una pensión.", "You can't sleep here. Two nights. We'll pay for a guesthouse."),
    Z("Die Pension ist in der Nähe vom Ostbahnhof. Marta nimmt den Koffer. Den grünen.", "La pensión está cerca de la estación del Este. Marta coge la maleta. La verde.", "The guesthouse is near the Ostbahnhof, the East station. Marta takes the suitcase. The green one."),
    Z("An der Rezeption sitzt ein Nachtportier. Er macht ein Kreuzworträtsel.", "En la recepción hay un portero de noche. Está haciendo un crucigrama.", "A night porter is sitting at reception. He is doing a crossword."),
    N("Las dos y media de la madrugada. Chaleco de punto. Levanta la vista sin ninguna prisa.",
      "Half past two in the morning. A knitted waistcoat. He looks up in no hurry at all."),
    Z("—Guten Abend. Haben Sie bei uns gebucht?", "Buenas noches. ¿Tiene reserva con nosotros?", "Good evening. Have you booked with us?"),
    Z("—Ja. Auf den Namen Ruiz.", "Sí. A nombre de Ruiz.", "Yes. Under the name Ruiz."),
    Z("—Wie bitte? Können Sie das buchstabieren?", "¿Perdón? ¿Puede deletrearlo?", "Sorry? Could you spell that?"),
    Z("—R wie Rocío. U wie … Úbeda. I wie Isabel. Z wie … Zaragoza.", "R de Rocío. U de… Úbeda. I de Isabel. Z de… Zaragoza.", "R for Rocío. U for… Úbeda. I for Isabel. Z for… Zaragoza."),
    N("El portero escribe muy despacio. Luego la mira por encima de las gafas.",
      "The porter writes very slowly. Then he looks at her over his glasses."),
    Z("—Bei uns sagt man: R wie Richard, U wie Ulrich, I wie Ida, Z wie Zeppelin.", "Aquí decimos: R de Richard, U de Ulrich, I de Ida, Z de Zeppelin.", "Here we say: R for Richard, U for Ulrich, I for Ida, Z for Zeppelin."),
    Z("—Zeppelin. Das ist schön.", "Zeppelin. Qué bonito.", "Zeppelin. That's nice."),
    Z("—Ruiz. Zwei Nächte, richtig?", "Ruiz. Dos noches, ¿verdad?", "Ruiz. Two nights, is that right?"),
    Z("—Genau. Ist das Frühstück dabei?", "Exacto. ¿El desayuno está incluido?", "Exactly. Is breakfast included?"),
    Z("—Ja, von sieben bis zehn. Ihren Ausweis, bitte.", "Sí, de siete a diez. Su documento de identidad, por favor.", "Yes, from seven till ten. Your ID, please."),
    N("Marta le da el pasaporte: lo segundo que salvó del agua. A cambio recibe una llave de verdad, de metal, con un llavero de madera enorme.",
      "Marta gives him her passport: the second thing she saved from the water. In return she gets a real key, made of metal, with a huge wooden key ring."),
    Z("—Hier ist Ihr Schlüssel. Zimmer vierzehn.", "Aquí tiene su llave. Habitación catorce.", "Here's your key. Room fourteen."),
    Z("—Danke. In welchem Stock ist das Zimmer?", "Gracias. ¿En qué piso está la habitación?", "Thank you. Which floor is the room on?"),
    Z("—Im ersten Stock. Der Aufzug ist gleich rechts.", "En el primer piso. El ascensor está aquí mismo, a la derecha.", "On the first floor. The lift is just on the right."),
    N("El ascensor es tan pequeño que Marta y la maleta tienen que subir por turnos. Sube primero la maleta.",
      "The lift is so small that Marta and the suitcase have to go up in turns. The suitcase goes first."),
    Z("Das Zimmer ist klein und ruhig. Es ist warm. Das Bett ist weich.", "La habitación es pequeña y tranquila. Hace calor. La cama es blanda.", "The room is small and quiet. It's warm. The bed is soft."),
    N("Marta pone la funda en la mesilla, bien a la vista, y programa dos alarmas: las seis y media y las seis y treinta y cinco. Por si acaso. En el espejo: pálida, despeinada, con fiebre y con un plan.",
      "Marta puts the sleeve on the bedside table, in plain sight, and sets two alarms: half past six and six thirty-five. Just in case. In the mirror: pale, dishevelled, feverish, and with a plan."),
    Z("Zwei Wecker. Eine Klarsichthülle. Jetzt bin ich wirklich Deutsche.", "Dos alarmas. Una funda de plástico. Ahora sí que soy alemana.", "Two alarms. A plastic sleeve. Now I really am German.")
  ]),

  // ── Station 10 · FAMILIE ────────────────────────────────────────────
  S('fundament', 10, 'familie', "Klara mit K?",
    "La cita por fin: un funcionario con una impresora lenta, una hermana que se escribe con C — y por la noche llama Sevilla.",
    "The appointment at last: an official with a slow printer, a sister spelt with a C — and in the evening, Seville calls.",
  [
    N("Jueves, veinticuatro de octubre. Treinta y siete coma cuatro. Desayuno en la pensión a las siete en punto: un café y una Semmel. Lo dice sin pensar: Semmel.",
      "Thursday, the twenty-fourth of October. Thirty-seven point four. Breakfast at the guesthouse at seven sharp: a coffee and a Semmel. She says it without thinking: Semmel."),
    Z("Um acht Uhr fünf steht Marta vor dem Bürgerbüro. Zehn Minuten zu früh.", "A las ocho y cinco, Marta está delante del Bürgerbüro. Diez minutos antes de la hora.", "At five past eight, Marta is standing outside the Bürgerbüro. Ten minutes early."),
    N("Diez minutos antes. Si su madre la viera, llamaría a un médico.",
      "Ten minutes early. If her mother could see her, she would call a doctor."),
    Z("Sie hat den Schal, den Pass und die Klarsichthülle.", "Lleva la bufanda, el pasaporte y la funda de plástico.", "She has her scarf, her passport and the plastic sleeve."),
    Z("Auf dem Bildschirm steht eine Nummer: B 017. Platz vier.", "En la pantalla aparece un número: B 017. Puesto cuatro.", "A number appears on the screen: B 017. Desk four."),
    Z("An Platz vier sitzt ein Mann mit Schnurrbart. Auf dem Tisch steht ein Kaktus. Das ist Herr Gruber.", "En el puesto cuatro hay un hombre con bigote. En la mesa hay un cactus. Es el señor Gruber.", "At desk four sits a man with a moustache. There's a cactus on the desk. That's Herr Gruber."),
    Z("—Guten Morgen. Ich habe einen Termin um acht Uhr fünfzehn. Hier ist mein Pass.", "Buenos días. Tengo una cita a las ocho y cuarto. Aquí tiene mi pasaporte.", "Good morning. I have an appointment at quarter past eight. Here's my passport."),
    Z("—Guten Morgen, Frau Ruiz. Das Formular? Und die Wohnungsgeberbestätigung?", "Buenos días, señora Ruiz. ¿El formulario? ¿Y la confirmación de la casera?", "Good morning, Frau Ruiz. The form? And the landlord's confirmation?"),
    Z("Marta gibt ihm die Klarsichthülle. Herr Gruber liest. Er liest lange.", "Marta le da la funda de plástico. El señor Gruber lee. Lee mucho rato.", "Marta gives him the plastic sleeve. Herr Gruber reads. He reads for a long time."),
    Z("—Grün. Interessant.", "Verde. Interesante.", "Green. Interesting."),
    Z("—Frau Ostermeier unterschreibt immer grün. Blau ist für Beamte.", "La señora Ostermeier siempre firma en verde. El azul es para los funcionarios.", "Frau Ostermeier always signs in green. Blue is for civil servants."),
    N("Herr Gruber, funcionario, sostiene un bolígrafo azul. Lo mira. Mira a Marta. Y por primera vez, debajo del bigote, algo se mueve.",
      "Herr Gruber, civil servant, is holding a blue pen. He looks at it. He looks at Marta. And for the first time, something moves under the moustache."),
    Z("—Alles in Ordnung. Einen Moment. Der Drucker ist langsam.", "Todo en orden. Un momento. La impresora es lenta.", "Everything's in order. One moment. The printer is slow."),
    Z("Der Drucker brummt. Er druckt nicht. Er brummt nur.", "La impresora zumba. No imprime. Solo zumba.", "The printer hums. It doesn't print. It just hums."),
    Z("—Erzählen Sie mal, Frau Ruiz. Haben Sie Geschwister?", "Cuénteme, señora Ruiz. ¿Tiene hermanos?", "Tell me, Frau Ruiz. Have you got any brothers or sisters?"),
    Z("—Ja, ich habe eine Schwester.", "Sí, tengo una hermana.", "Yes, I've got a sister."),
    Z("—Schön! Und wie heißt sie?", "¡Qué bien! ¿Y cómo se llama?", "How nice! And what's her name?"),
    Z("—Sie heißt Clara.", "Se llama Clara.", "Her name is Clara."),
    Z("—Klara mit K?", "¿Clara con K?", "Clara with a K?"),
    Z("—Nein. Clara mit C. In Spanien schreibt man Clara mit C.", "No. Clara con C. En España, Clara se escribe con C.", "No. Clara with a C. In Spain, Clara is spelt with a C."),
    Z("—Mit C. Ein hübscher Name. Wie alt ist sie denn?", "Con C. Un nombre muy bonito. ¿Y cuántos años tiene?", "With a C. A lovely name. And how old is she?"),
    Z("—Sie ist zwölf.", "Tiene doce años.", "She's twelve."),
    Z("—Zwölf! Meine Tochter ist auch zwölf. Sie spricht nicht mehr mit mir. Nur mit ihrem Handy.", "¡Doce! Mi hija también tiene doce. Ya no habla conmigo. Solo con el móvil.", "Twelve! My daughter is twelve too. She doesn't talk to me any more. Only to her phone."),
    Z("—Meine Schwester auch.", "Mi hermana también.", "So does my sister."),
    N("Herr Gruber suspira. Marta suspira. Dos países, exactamente el mismo problema.",
      "Herr Gruber sighs. Marta sighs. Two countries, exactly the same problem."),
    Z("Endlich druckt der Drucker. Herr Gruber nimmt einen Stempel. Bumm.", "Por fin la impresora imprime. El señor Gruber coge un sello. Pum.", "At last the printer prints. Herr Gruber picks up a stamp. Thump."),
    Z("MELDEBESCHEINIGUNG · Marta Ruiz · Wörthstraße 12 · München", "CERTIFICADO DE EMPADRONAMIENTO · Marta Ruiz · Wörthstraße 12 · Múnich", "REGISTRATION CERTIFICATE · Marta Ruiz · Wörthstraße 12 · Munich"),
    Z("—So. Die Steuer-ID kommt mit der Post. Jetzt sind Sie Münchnerin.", "Listo. El número fiscal le llegará por correo. Ahora es usted muniquesa.", "There. Your tax ID will come in the post. Now you're a Münchnerin."),
    N("Münchnerin. Con esa -in final que convierte a los muniqueses en muniquesas. Marta manda una foto del papel a Recursos Humanos. Siete días antes del plazo. Luego, como dijo la doctora, a la cama.",
      "Münchnerin. With that -in at the end that turns men of Munich into women of Munich. Marta sends a photo of the paper to HR. Seven days before the deadline. Then, as the doctor said, bed."),
    Z("Am Abend macht Marta einen Videoanruf. Nach Sevilla.", "Por la noche, Marta hace una videollamada. A Sevilla.", "In the evening, Marta makes a video call. To Seville."),
    N("En la pantalla, el bar de su padre en Triana, con el fútbol en la tele. Manolo, con el trapo al hombro. Rocío, empujando para salir en la imagen. Y Clara, que ha aprendido una frase en YouTube y quiere usarla ya.",
      "On the screen, her father's bar in Triana, with football on the TV. Manolo, a tea towel over his shoulder. Rocío, pushing to get into the picture. And Clara, who has learnt a phrase on YouTube and wants to use it right now."),
    Z("—Hallo, Marta! Wie geht's?", "¡Hola, Marta! ¿Qué tal?", "Hi, Marta! How are you?"),
    Z("—Hallo, Clara! Sehr gut. Ich bin jetzt Münchnerin.", "¡Hola, Clara! Muy bien. Ahora soy muniquesa.", "Hi, Clara! Very well. I'm a Münchnerin now."),
    Z("Clara versteht nichts. Aber sie klatscht.", "Clara no entiende nada. Pero aplaude.", "Clara doesn't understand a word. But she claps."),
    N("Su madre le pregunta si come bien. Su padre le pregunta si allí hay fútbol de verdad. Y luego Rocío se acerca tanto a la cámara que solo se le ve un ojo.",
      "Her mother asks whether she's eating properly. Her father asks whether they have real football there. And then Rocío comes so close to the camera that only one eye is visible."),
    N("«Hemos comprado los billetes. Vamos en diciembre. Los tres. Para el mercadillo de Navidad, ese de las fotos… ¿cómo se dice?»",
      "“We've bought the tickets. We're coming in December. All three of us. For the Christmas market, the one in the photos… what's it called?”"),
    Z("—Zum Christkindlmarkt. Ihr kommt alle drei? Mama, Papa und Clara? Hier, nach München?", "Al Christkindlmarkt. ¿Venís los tres? ¿Mamá, papá y Clara? ¿Aquí, a Múnich?", "To the Christkindlmarkt. You're all three coming? Mum, Dad and Clara? Here, to Munich?"),
    N("Manolo levanta una caña ante la cámara, como si brindara con media ciudad. Marta se ríe.",
      "Manolo raises a small beer to the camera, as if toasting half the city. Marta laughs."),
    Z("Draußen regnet es wieder. Heute ist das egal.", "Fuera vuelve a llover. Hoy da igual.", "It's raining again outside. Today it doesn't matter."),
    Z("Meine Familie wohnt in Sevilla. Ich wohne in München. Ich bin Münchnerin. Ein bisschen.", "Mi familia vive en Sevilla. Yo vivo en Múnich. Soy muniquesa. Un poco.", "My family lives in Seville. I live in Munich. I'm a Münchnerin. A little.")
  ])

  ];
})(window);

/* ──────────────────────────────────────────────────────────────────────────
   lr-parts/marta-2.js — „Marta in München" · Teil II „Der Besuch" + Epilog
   Zielsprache Deutsch · Muttersprachen es/en · Stationen 11–21
   Teil II = die zehn A2-Szenen des Lernpfads (a2.*), Epilog = reine Prosa.
   ────────────────────────────────────────────────────────────────────────── */
(function (w) {
  var K = w.__LR_PARTS_MARTA = w.__LR_PARTS_MARTA || {};
  function N(a, b) { return { na: { es: a, en: b } }; }
  function Z(z, a, b) { var o = { z: z }; if (a) o.tr = { es: a, en: b }; return o; }
  function P(p) { return { p: p }; }
  function S(level, n, thema, title, teaserA, teaserB, body) {
    return { level: level, n: n, thema: thema, title: title, teaser: { es: teaserA, en: teaserB }, body: body };
  }

  K.teil2 = [

  // ── Station 11 · TAXI (A2) ────────────────────────────────────────────
  S("aufbau", 11, "taxi", "Stau auf der A9",
    "Seis de diciembre: la familia aterriza a las seis menos veinte, la A9 es un aparcamiento y al volante, cómo no, está Gerti.",
    "The sixth of December: the family lands at twenty to six, the A9 is a car park and, of course, Gerti is at the wheel.",
  [
    Z("Die Wochen vergingen. Es wurde Dezember.", "Pasaron las semanas. Llegó diciembre.", "The weeks went by. December came."),
    Z("Marta verlief sich nicht mehr in Haidhausen. Jeden Morgen kaufte sie zwei Semmeln bei Frau Schmid. Sie sagte jetzt »Semmeln«. Meistens.", "Marta ya no se perdía en Haidhausen. Cada mañana compraba dos panecillos en la panadería de la señora Schmid. Ahora decía «Semmeln». Casi siempre.", "Marta no longer got lost in Haidhausen. Every morning she bought two rolls from Frau Schmid. She said “Semmeln” now. Mostly."),
    N("Jonas llevaba la cuenta en una lista pegada a la nevera: «Semmel: 31. Brötchen: 6». Marta decía que aquella lista era propaganda bávara. Pero no la quitaba.",
      "Jonas kept count on a list stuck to the fridge: “Semmel: 31. Brötchen: 6.” Marta said the list was Bavarian propaganda. But she didn't take it down."),
    Z("Am 6. Dezember war Nikolaustag. Vor jeder Zimmertür in der WG stand ein Stiefel mit Mandarinen und Schokolade.", "El 6 de diciembre era San Nicolás. Delante de cada puerta del piso había una bota con mandarinas y chocolate.", "The sixth of December was St Nicholas' Day. Outside every bedroom door in the flat stood a boot with tangerines and chocolate."),
    Z("Und um 17:40 Uhr landete ihre Familie aus Sevilla.", "Y a las seis menos veinte aterrizaba su familia, que venía de Sevilla.", "And at twenty to six her family was landing from Seville."),
    N("A las cinco menos diez, Marta seguía en la universidad. Su catedrático le había dicho tres veces «solo una cosita más». En Alemania, había aprendido Marta, «una cosita más» nunca es una cosita.",
      "At ten to five, Marta was still at the university. Her professor had said three times: “just one more little thing”. In Germany, Marta had learnt, “one more little thing” is never little."),
    Z("Vor der Uni wartete ein Taxi. Am Steuer: roter Lippenstift und eine Mütze mit Rentier.", "Delante de la universidad esperaba un taxi. Al volante: pintalabios rojo y un gorro con un reno.", "A taxi was waiting outside the university. At the wheel: red lipstick and a hat with a reindeer on it."),
    Z("—Servus, Spanierin! Wohin darf ich Sie bringen?", "¡Hola, española! ¿Adónde la llevo?", "Hello there, Spaniard! Where can I take you?"),
    Z("—Gerti! Zum Flughafen, bitte. Ich bin in Eile. Meine Familie landet um zwanzig vor sechs.", "¡Gerti! Al aeropuerto, por favor. Tengo prisa. Mi familia aterriza a las seis menos veinte.", "Gerti! To the airport, please. I'm in a hurry. My family lands at twenty to six."),
    Z("—Zum Flughafen? Wie im Oktober. Wissen Sie was? Wir sind jetzt per du, gell? Ich bin die Gerti.", "¿Al aeropuerto? Como en octubre. ¿Sabe qué? Ahora ya nos tuteamos, ¿vale? Yo soy Gerti.", "To the airport? Like in October. You know what? We're on first-name terms now, all right? I'm Gerti."),
    N("Marta ya sabía que Gerti se llamaba Gerti. Pero no era eso lo que le estaba diciendo. En alemán, el «du» no se toma: se ofrece. Y lo ofrece la persona mayor. Gerti acababa de hacerle un regalo.",
      "Marta already knew that Gerti was called Gerti. But that wasn't what she was telling her. In German, you don't take the informal “du”: it is offered. And the older person offers it. Gerti had just given her a present."),
    Z("—Danke, Gerti. Ich bin die Marta.", "Gracias, Gerti. Yo soy Marta.", "Thanks, Gerti. I'm Marta."),
    Z("—Also. Auf der Autobahn ist Stau. Die A9 ist heute ein Parkplatz.", "Bueno. En la autopista hay atasco. Hoy la A9 es un aparcamiento.", "Right. There's a jam on the motorway. Today the A9 is a car park."),
    Z("—Und was machen wir?", "¿Y qué hacemos?", "So what do we do?"),
    Z("—Soll ich durch die Stadt fahren und dann über die Dörfer?", "¿Voy por la ciudad y luego por los pueblos?", "Shall I go through the city and then through the villages?"),
    Z("—Ist das denn schneller?", "¿Y es más rápido?", "Is that quicker, then?"),
    Z("—Bei dem Verkehr ja. Zehn Minuten weniger. Festhalten!", "Con este tráfico, sí. Diez minutos menos. ¡Agárrate!", "With this traffic, yes. Ten minutes less. Hold on!"),
    Z("Gerti bog links ab, dann rechts, dann fuhr sie durch eine Baustelle. Dann kam eine Umleitung. Und dann noch eine.", "Gerti giró a la izquierda, luego a la derecha y luego atravesó unas obras. Después vino un desvío. Y después otro.", "Gerti turned left, then right, then drove through some roadworks. Then came a diversion. And then another one."),
    Z("—München hat mehr Baustellen als Kirchen. Und wir haben viele Kirchen.", "Múnich tiene más obras que iglesias. Y tenemos muchas iglesias.", "Munich has more roadworks than churches. And we have a lot of churches."),
    N("El móvil de Marta vibró. Era su madre, con la foto de un cartel amarillo del aeropuerto: «¿Ausgang está muy lejos? Todo el mundo va a Ausgang». Marta le contestó que Ausgang no era una ciudad. Era la salida.",
      "Marta's phone buzzed. It was her mother, with a photo of a yellow sign at the airport: “Is Ausgang very far? Everybody's going to Ausgang.” Marta replied that Ausgang wasn't a town. It was the exit."),
    Z("Um 17:58 Uhr hielt das Taxi am Terminal 2. Marta war achtzehn Minuten zu spät.", "A las seis menos dos, el taxi paró en la Terminal 2. Marta llegaba dieciocho minutos tarde.", "At two minutes to six, the taxi stopped at Terminal 2. Marta was eighteen minutes late."),
    Z("Aber die Koffer waren noch nicht da. Marta war zu spät und trotzdem pünktlich.", "Pero las maletas todavía no habían salido. Marta llegaba tarde y, aun así, puntual.", "But the suitcases hadn't come out yet. Marta was late and still on time."),
    N("Luego, todo a la vez: Clara corriendo hacia ella; su madre con tres abrigos puestos, uno encima de otro, «por si acaso»; y su padre empujando un carro con una caja de cartón.",
      "Then everything at once: Clara running towards her; her mother wearing three coats, one on top of the other, “just in case”; and her father pushing a trolley with a cardboard box."),
    Z("Auf dem Karton stand: NARANJAS DE SEVILLA. Zwölf Kilo.", "En la caja ponía: NARANJAS DE SEVILLA. Doce kilos.", "The box said: NARANJAS DE SEVILLA. Twelve kilos."),
    N("—Para tus alemanes —dijo su padre—. Que vean lo que es el sol. Y mientras Gerti metía la caja en el maletero, añadió en voz baja—: Pídele un recibo. Es para Hacienda. —Papá, estás de vacaciones. —Hacienda no tiene vacaciones.",
      "“For your Germans,” said her father. “So they can see what sunshine is.” And while Gerti put the box in the boot, he added quietly: “Ask her for a receipt. It's for the tax office.” “Dad, you're on holiday.” “The tax office doesn't go on holiday.”"),
    Z("—Gerti, bekomme ich am Ende eine Quittung? Für meinen Vater. Er hat eine Bar in Sevilla.", "Gerti, ¿me das un recibo al final? Es para mi padre. Tiene un bar en Sevilla.", "Gerti, can I have a receipt at the end? It's for my father. He has a bar in Seville."),
    Z("—Ein Wirt! Dann sind wir Kollegen. Wirte und Taxler wissen alles über eine Stadt.", "¡Uno de bares! Entonces somos colegas. Los de los bares y los taxistas lo saben todo de una ciudad.", "A publican! Then we're colleagues. Publicans and cabbies know everything about a city."),
    Z("Vor dem Hotel schrieb Gerti die Quittung. Dann probierte sie eine Orange.", "Delante del hotel, Gerti escribió el recibo. Después probó una naranja.", "Outside the hotel, Gerti wrote the receipt. Then she tried an orange."),
    Z("Sie kaute lange. Ihr Gesicht bewegte sich nicht.", "Masticó un buen rato. No movió ni un músculo de la cara.", "She chewed for a long time. Her face didn't move."),
    Z("—Passt schon.", "Está bien.", "That'll do."),
    N("Su padre miró a Marta, esperando la traducción. —Dice que es la mejor naranja de su vida. Su padre asintió, muy serio. Algunas traducciones no son exactas. Pero son verdad.",
      "Her father looked at Marta, waiting for the translation. “She says it's the best orange of her life.” Her father nodded, very seriously. Some translations aren't exact. But they're true.")
  ]),

  // ── Station 12 · HOTEL (A2) ───────────────────────────────────────────
  S("aufbau", 12, "hotel", "Die Heizung funktioniert nicht",
    "Primera noche en el hotel: la calefacción no funciona, no hay agua caliente y, por una vez, Marta no es la única que tiene frío.",
    "First night at the hotel: the heating isn't working, there's no hot water and, for once, Marta isn't the only one who's cold.",
  [
    Z("Die Familie wohnte in einem kleinen Hotel am Sendlinger Tor. Drei Sterne, viel Holz und ein Hirschgeweih im Frühstücksraum.", "La familia se alojaba en un hotel pequeño junto al Sendlinger Tor. Tres estrellas, mucha madera y una cornamenta de ciervo en el comedor del desayuno.", "The family was staying in a small hotel by the Sendlinger Tor. Three stars, a lot of wood and a set of antlers in the breakfast room."),
    Z("Am Samstag um sieben Uhr morgens klingelte Martas Handy. Es war ihre Mutter.", "El sábado, a las siete de la mañana, sonó el móvil de Marta. Era su madre.", "On Saturday at seven in the morning, Marta's phone rang. It was her mother."),
    N("—Marta, la calefacción no funciona. Hace un frío que pela. Y no hay agua caliente. Tu padre se ha lavado con el agua del hervidor, como en la mili. Clara ha dormido con el anorak.",
      "“Marta, the heating isn't working. It's freezing. And there's no hot water. Your father washed with water from the kettle, like in his army days. Clara slept in her anorak.”"),
    N("Marta escuchó y sintió algo pequeño y feo: alegría. Desde octubre era la única que tenía frío en Múnich. Ahora, por fin, tenía compañía.",
      "Marta listened and felt something small and ugly: joy. Since October she had been the only one in Munich who was cold. Now, at last, she had company."),
    Z("Zwanzig Minuten später stand sie an der Rezeption. Hinter dem Tresen saß ein junger Mann. Auf seinem Namensschild stand: Florian.", "Veinte minutos después estaba en la recepción. Detrás del mostrador había un chico joven. En su placa ponía: Florian.", "Twenty minutes later she was at reception. A young man sat behind the desk. His name badge said: Florian."),
    Z("—Guten Morgen. Alles zu Ihrer Zufriedenheit?", "Buenos días. ¿Está todo a su gusto?", "Good morning. Is everything to your satisfaction?"),
    Z("—Guten Morgen. Nicht ganz. Meine Familie ist in Zimmer 212. Leider funktioniert die Heizung nicht.", "Buenos días. No del todo. Mi familia está en la habitación 212. Lamentablemente, la calefacción no funciona.", "Good morning. Not quite. My family is in room 212. Unfortunately, the heating isn't working."),
    Z("—Das tut mir leid. Seit wann denn?", "Lo siento. ¿Desde cuándo?", "I'm sorry. Since when?"),
    Z("—Seit gestern Abend. Und warmes Wasser gibt es auch nicht.", "Desde anoche. Y tampoco hay agua caliente.", "Since last night. And there's no hot water either."),
    Z("—Ich schicke sofort jemanden hoch. Oder möchten Sie lieber wechseln?", "Ahora mismo mando a alguien arriba. ¿O prefieren cambiar de habitación?", "I'll send someone up straight away. Or would you rather change rooms?"),
    N("Marta tradujo por teléfono. Su padre: «Que lo arreglen, que yo de calefacciones sé un rato». Su madre: «Nos cambiamos». Clara: «¿Hay alguna con vistas a algo?». Su padre no sabía nada de calefacciones. Marta decidió.",
      "Marta translated over the phone. Her father: “Let them fix it, I know a thing or two about heating.” Her mother: “We're moving.” Clara: “Is there one with a view of something?” Her father knew nothing about heating. Marta decided."),
    Z("—Ich würde lieber wechseln, wenn das geht. Die 212 ist auch sehr laut. Die Tram fährt direkt unter dem Fenster.", "Preferiría cambiar, si es posible. Además, la 212 es muy ruidosa. El tranvía pasa justo debajo de la ventana.", "I'd rather change, if that's possible. Room 212 is also very noisy. The tram runs right under the window."),
    Z("—Nur bis halb zwei. Ab fünf fährt sie wieder.", "Solo hasta la una y media. A partir de las cinco vuelve a pasar.", "Only until half past one. From five it runs again."),
    N("Marta pensó en Jonas. A lo mejor era él quien había despertado a su familia a las cinco. Decidió no investigarlo.",
      "Marta thought of Jonas. Maybe he was the one who had woken her family at five. She decided not to look into it."),
    Z("—Ich gebe Ihnen die 305. Die liegt zum Hof und ist viel ruhiger. Und die Heizung dort ist neu.", "Les doy la 305. Da al patio y es mucho más tranquila. Y la calefacción de esa habitación es nueva.", "I'll give you 305. It faces the courtyard and is much quieter. And the heating in there is new."),
    Z("—Noch etwas: Im Bad gibt es nur zwei Handtücher. Und meine Familie ist zu dritt.", "Otra cosa: en el baño solo hay dos toallas. Y mi familia son tres.", "One more thing: there are only two towels in the bathroom. And there are three of them in my family."),
    Z("—Kein Problem, ich bringe sofort drei neue hoch. Geben Sie mir bitte Bescheid, wenn noch etwas fehlt.", "No hay problema, ahora mismo subo tres nuevas. Avíseme, por favor, si falta algo más.", "No problem, I'll bring three new ones up straight away. Please let me know if anything else is missing."),
    Z("—Vielen Dank. Sehr nett.", "Muchas gracias. Muy amable.", "Thank you very much. That's very kind."),
    N("Cuando Marta se dio la vuelta, su madre estaba detrás de ella, con los tres abrigos puestos. Lo había oído todo. La miraba como si fuera otra persona. —¿Desde cuándo hablas así?",
      "When Marta turned round, her mother was standing behind her, all three coats on. She had heard everything. She was looking at her as if she were someone else. “Since when do you talk like that?”"),
    N("Desde el Bürgerbüro, pensó Marta. Desde que un funcionario le preguntó si Clara se escribía con K. Después de eso, ningún mostrador del mundo le daba miedo.",
      "Since the Bürgerbüro, Marta thought. Since an official asked her whether Clara was spelt with a K. After that, no counter in the world could frighten her."),
    Z("Das Zimmer 305 war kleiner. Aber es war warm. Sehr warm.", "La habitación 305 era más pequeña. Pero hacía calor. Mucho calor.", "Room 305 was smaller. But it was warm. Very warm."),
    Z("Ihr Vater öffnete das Fenster. Ihre Mutter zog zwei Mäntel aus. Clara zog den Anorak aus.", "Su padre abrió la ventana. Su madre se quitó dos abrigos. Clara se quitó el anorak.", "Her father opened the window. Her mother took off two coats. Clara took off her anorak."),
    Z("Und Marta zog ihre Jacke aus. Zum ersten Mal seit dem Föhn.", "Y Marta se quitó la chaqueta. Por primera vez desde el día del Föhn.", "And Marta took off her jacket. For the first time since the Föhn.")
  ]),

  // ── Station 13 · CAFÉ (A2) ────────────────────────────────────────────
  S("aufbau", 13, "cafe", "Der Kaffee ist leider kalt",
    "Marta lleva a su familia al café de la señora Schmid, donde nadie se ha quejado jamás. El café está tibio. Y su madre es alérgica a los frutos secos.",
    "Marta takes her family to Frau Schmid's café, where nobody has ever complained. The coffee is lukewarm. And her mother is allergic to nuts.",
  [
    Z("Am Montag frühstückte die Familie bei Frau Schmid, im Café unter der WG.", "El lunes, la familia desayunó en el café de la señora Schmid, debajo del piso.", "On Monday the family had breakfast at Frau Schmid's, in the café below the flat."),
    N("Aylin bajó también. Por curiosidad, dijo. En realidad quería ver la cara de la señora Schmid ante cuatro sevillanos a la vez.",
      "Aylin came down too. Out of curiosity, she said. Actually, she wanted to see Frau Schmid's face when faced with four Sevillians at once."),
    Z("Frau Schmid stand hinter der Theke wie immer: weiße Schürze, Brille an einer Kette, kein Lächeln.", "La señora Schmid estaba detrás del mostrador, como siempre: delantal blanco, gafas colgadas de una cadena, ni una sonrisa.", "Frau Schmid stood behind the counter as always: white apron, glasses on a chain, not a smile."),
    Z("—Grüß Gott. Was darf's sein?", "Buenos días. ¿Qué va a ser?", "Good morning. What can I get you?"),
    Z("—Vier Kaffee, eine heiße Schokolade und sechs Semmeln, bitte.", "Cuatro cafés, un chocolate caliente y seis panecillos, por favor.", "Four coffees, a hot chocolate and six rolls, please."),
    Z("Frau Schmid sah Marta über die Brille an. Semmeln. Nicht Brötchen. Sie nickte. Fast zufrieden.", "La señora Schmid miró a Marta por encima de las gafas. Semmeln. No Brötchen. Asintió. Casi satisfecha.", "Frau Schmid looked at Marta over her glasses. Semmeln. Not Brötchen. She nodded. Almost satisfied."),
    N("Su padre estudiaba la cafetera de la señora Schmid como otros estudian un cuadro en el Prado. Treinta años detrás de una barra: de cafeteras, él sabía.",
      "Her father studied Frau Schmid's coffee machine the way other people study a painting in the Prado. Thirty years behind a bar: coffee machines, he knew about."),
    N("Su madre, en cambio, miraba la vitrina de los pasteles. Era alérgica a los frutos secos desde niña. En Sevilla preguntaba en cada bar. En Múnich no sabía cómo.",
      "Her mother, on the other hand, was looking at the cake display. She had been allergic to nuts since childhood. In Seville she asked in every bar. In Munich she didn't know how."),
    Z("—Und noch etwas: Sind in dem Kuchen Nüsse? Meine Mutter ist nämlich allergisch.", "Y otra cosa: ¿ese pastel lleva frutos secos? Es que mi madre es alérgica.", "And one more thing: are there nuts in that cake? My mother is allergic, you see."),
    Z("—In dem schon. Haselnüsse. Und in den Plätzchen sind Mandeln.", "Ese sí. Avellanas. Y las galletas llevan almendras.", "That one, yes. Hazelnuts. And there are almonds in the biscuits."),
    Z("—Und im Zitronenkuchen?", "¿Y el bizcocho de limón?", "And the lemon cake?"),
    Z("—Der Zitronenkuchen ist nussfrei. Zitrone, Mehl, Butter, Eier, Zucker. Sonst nichts.", "El bizcocho de limón no lleva frutos secos. Limón, harina, mantequilla, huevos, azúcar. Nada más.", "The lemon cake is nut-free. Lemon, flour, butter, eggs, sugar. Nothing else."),
    Z("—Gut. Dann den Zitronenkuchen, bitte.", "Bien. Entonces, el de limón, por favor.", "Good. The lemon cake, then, please."),
    Z("Dann trank ihr Vater einen Schluck Kaffee. Er sagte nichts. Er stellte die Tasse sehr langsam wieder hin.", "Luego su padre bebió un sorbo de café. No dijo nada. Dejó la taza muy despacio.", "Then her father took a sip of coffee. He said nothing. He put the cup down very slowly."),
    N("—Tibio —susurró. En Triana, eso era un insulto.",
      "“Lukewarm,” he whispered. In Triana, that was an insult."),
    Z("Aylin beugte sich zu Marta: »Bei Frau Schmid beschwert sich niemand. Nicht einmal der Pfarrer.«", "Aylin se inclinó hacia Marta: «A la señora Schmid no se le queja nadie. Ni siquiera el cura».", "Aylin leant towards Marta. “Nobody complains to Frau Schmid. Not even the parish priest.”"),
    Z("Frau Schmid kam an den Tisch.", "La señora Schmid se acercó a la mesa.", "Frau Schmid came over to the table."),
    Z("—Alles in Ordnung bei Ihnen?", "¿Todo bien por aquí?", "Is everything all right here?"),
    Z("Marta holte tief Luft.", "Marta respiró hondo.", "Marta took a deep breath."),
    Z("—Entschuldigung, der Kaffee ist leider lauwarm.", "Perdone, pero el café está tibio.", "Excuse me, I'm afraid the coffee is lukewarm."),
    N("Silencio. El hombre del periódico dejó de pasar páginas. Aylin cerró los ojos.",
      "Silence. The man with the newspaper stopped turning the pages. Aylin closed her eyes."),
    Z("Frau Schmid berührte die Tasse mit einem Finger.", "La señora Schmid tocó la taza con un dedo.", "Frau Schmid touched the cup with one finger."),
    Z("—Das tut mir leid. Ich bringe Ihnen sofort einen neuen.", "Lo siento. Ahora mismo le traigo otro.", "I'm sorry. I'll bring you a new one straight away."),
    Z("Sie ging zur Maschine und schlug zweimal mit der Faust darauf. Martas Vater nickte. Genau so machte er es in Triana.", "Fue a la cafetera y le dio dos golpes con el puño. El padre de Marta asintió. Él hacía exactamente lo mismo en Triana.", "She went to the machine and hit it twice with her fist. Marta's father nodded. That was exactly what he did in Triana."),
    Z("Der neue Kaffee war heiß. Daneben lag eine kleine Tüte.", "El café nuevo estaba caliente. Al lado había una bolsita.", "The new coffee was hot. Next to it lay a little bag."),
    Z("—Für die Dame. Butterplätzchen, ohne Nüsse. Ich habe die Zutaten selbst kontrolliert. Zweimal.", "Para la señora. Galletas de mantequilla, sin frutos secos. He revisado los ingredientes yo misma. Dos veces.", "For the lady. Butter biscuits, no nuts. I checked the ingredients myself. Twice."),
    Z("—Was kostet das?", "¿Cuánto es?", "How much is that?"),
    Z("—Nichts. Das ist ein Geschenk.", "Nada. Es un regalo.", "Nothing. It's a present."),
    N("Su padre levantó el pulgar. La señora Schmid lo miró. Dos personas de barra, sin una palabra en común, se entendieron perfectamente.",
      "Her father gave a thumbs-up. Frau Schmid looked at him. Two people who worked behind a counter, without a single word in common, understood each other perfectly."),
    Z("Aylin flüsterte: »Hast du das gesehen? Sie hat gelächelt.«", "Aylin susurró: «¿Lo has visto? Ha sonreído».", "Aylin whispered: “Did you see that? She smiled.”"),
    Z("—Unmöglich. Das war der Dampf von der Maschine.", "Imposible. Era el vapor de la cafetera.", "Impossible. That was the steam from the machine."),
    N("Esa noche, su madre comió galletas de mantequilla hasta las once. Y en la escalera dijo algo que Marta no olvidaría: «Esa mujer es como tu abuela. Riñe para no tener que abrazar».",
      "That night her mother ate butter biscuits until eleven. And on the stairs she said something Marta would never forget: “That woman is like your grandmother. She scolds so she doesn't have to hug.”")
  ]),

  // ── Station 14 · WEGBESCHREIBUNG (A2) ─────────────────────────────────
  S("aufbau", 14, "wegbeschreibung", "Moin!",
    "En el Isartor, una pareja de Hamburgo le pregunta a Marta cómo llegar al Deutsches Museum. Ella se lo explica en alemán. Y ellos la toman por muniquesa.",
    "At the Isartor, a couple from Hamburg ask Marta the way to the Deutsches Museum. She explains in German. And they take her for a local.",
  [
    Z("Am Dienstag wollte die Familie ins Deutsche Museum. Clara wollte Flugzeuge sehen, ihr Vater Schiffe und ihre Mutter ein Café.", "El martes, la familia quería ir al Deutsches Museum. Clara quería ver aviones; su padre, barcos; y su madre, una cafetería.", "On Tuesday the family wanted to go to the Deutsches Museum. Clara wanted to see aeroplanes, her father ships and her mother a café."),
    Z("Sie standen am Isartor. Es war kalt und grau. Marta trug zwei Schals.", "Estaban en el Isartor. Hacía frío y estaba gris. Marta llevaba dos bufandas.", "They were standing at the Isartor. It was cold and grey. Marta was wearing two scarves."),
    Z("Neben ihnen stand ein Paar mit Rucksäcken. Er hielt einen Stadtplan, sie hatte rote Ohren. Beide sahen sehr verloren aus.", "A su lado había una pareja con mochilas. Él sujetaba un plano; ella tenía las orejas rojas. Los dos parecían muy perdidos.", "Next to them stood a couple with rucksacks. He was holding a street map, she had red ears. They both looked very lost."),
    Z("—Suchen Sie etwas?", "¿Buscan algo?", "Are you looking for something?"),
    Z("—Moin! Ja. Entschuldigung, wie kommen wir von hier zum Deutschen Museum?", "¡Buenas! Sí. Perdone, ¿cómo llegamos desde aquí al Deutsches Museum?", "Hi there! Yes. Excuse me, how do we get to the Deutsches Museum from here?"),
    N("Marta se quedó un segundo en blanco. ¿Moin? Eran las doce del mediodía. Ella creía que Moin venía de Morgen, «mañana». Después se dio cuenta de otra cosa: le estaban preguntando a ella. No a su padre. No al plano. A ella.",
      "Marta went blank for a second. Moin? It was twelve noon. She had thought Moin came from Morgen, “morning”. Then she noticed something else: they were asking her. Not her father. Not the map. Her."),
    Z("—Das Deutsche Museum? Das ist ganz einfach.", "¿El Deutsches Museum? Es muy fácil.", "The Deutsches Museum? That's very easy."),
    Z("—Gehen Sie bis zur Ampel dort und überqueren Sie die Straße.", "Sigan hasta el semáforo de allí y crucen la calle.", "Go as far as the traffic lights over there and cross the road."),
    Z("—Und wie geht es dann weiter?", "¿Y después cómo seguimos?", "And then how do we go on?"),
    Z("—Sehen Sie das Café gegenüber? Dort beginnt die Zweibrückenstraße. Gehen Sie die Straße entlang, immer geradeaus, bis zur Isar.", "¿Ven el café de enfrente? Ahí empieza la Zweibrückenstraße. Sigan esa calle, todo recto, hasta el río Isar.", "Can you see the café opposite? That's where Zweibrückenstraße begins. Go along the street, straight on, as far as the Isar."),
    Z("—Das Museum liegt auf einer Insel. Nach der ersten Brücke biegen Sie rechts ab. Das große Gebäude mit dem Turm. Sie können es nicht verfehlen.", "El museo está en una isla. Después del primer puente, giren a la derecha. Es el edificio grande con la torre. No tiene pérdida.", "The museum is on an island. After the first bridge, turn right. The big building with the tower. You can't miss it."),
    Z("—Kann man zu Fuß hingehen?", "¿Se puede ir andando?", "Can we walk there?"),
    Z("—Ja, das ist eine Viertelstunde zu Fuß. Höchstens. Und am Eingang gibt es ein gutes Café.", "Sí, son quince minutos andando. Como mucho. Y en la entrada hay una cafetería buena.", "Yes, it's a quarter of an hour on foot. At most. And there's a good café at the entrance."),
    N("Su madre oyó «Café» y sonrió. Era la única palabra que necesitaba.",
      "Her mother heard “Café” and smiled. It was the only word she needed."),
    Z("—Super, danke! Sie sind von hier, ne?", "¡Genial, gracias! Usted es de aquí, ¿no?", "Great, thanks! You're from here, aren't you?"),
    Z("—Ich? Nein … seit Oktober.", "¿Yo? No… desde octubre.", "Me? No… since October."),
    Z("—Echt? Sie klingen wie eine Münchnerin. Na denn: Tschüss!", "¿En serio? Suena usted como una muniquesa. Bueno, pues: ¡adiós!", "Really? You sound like a Munich local. Well then: bye!"),
    Z("—Servus!", "¡Adiós!", "Bye!"),
    N("La pareja se fue hacia el semáforo. Su padre la miraba con los ojos muy abiertos. —Moin, Servus, Tschüss… ¿Cuántas formas de saludar tienen estos?",
      "The couple set off towards the lights. Her father was staring at her, eyes wide open. “Moin, Servus, Tschüss… How many ways of saying hello do these people have?”"),
    N("Marta se lo explicó. Moin es del norte y vale para todo el día. Grüß Gott y Servus son de aquí. Tschüss es adiós. —¿Y Servus? —Servus es hola. Y también adiós. Clara lo apuntó todo en su cuaderno, con flechas. —¿Y por qué tienen tantas? —Porque Alemania es muy grande y nadie se pone de acuerdo.",
      "Marta explained. Moin is from the north and works all day long. Grüß Gott and Servus are from here. Tschüss means goodbye. “And Servus?” “Servus is hello. And goodbye as well.” Clara wrote it all down in her notebook, with arrows. “And why do they have so many?” “Because Germany is very big and nobody can agree.”"),
    Z("Marta hatte »Servus« gesagt. Ohne nachzudenken. Wie eine Münchnerin.", "Marta había dicho «Servus». Sin pensarlo. Como una muniquesa.", "Marta had said “Servus”. Without thinking. Like a Munich local."),
    Z("Dann sah sie ihren Vater. Er ging schon los. Nach links.", "Luego vio a su padre. Ya se había puesto en marcha. Hacia la izquierda.", "Then she saw her father. He was already walking off. To the left."),
    Z("—Papa! Geradeaus! Bis zur Ampel!", "¡Papá! ¡Todo recto! ¡Hasta el semáforo!", "Dad! Straight on! As far as the lights!"),
    Z("Ihre Mutter lachte. Clara schrieb in ihr Heft: »Papa: immer links.«", "Su madre se rio. Clara escribió en su cuaderno: «Papá: siempre a la izquierda».", "Her mother laughed. Clara wrote in her notebook: “Dad: always left.”")
  ]),

  // ── Station 15 · EINKAUFEN (A2) ───────────────────────────────────────
  S("aufbau", 15, "einkaufen", "Eine Größe kleiner",
    "La camisa bávara que Marta le ha regalado a su padre le queda como una tienda de campaña. Toca cambiarla, con el tique en la mano.",
    "The Bavarian shirt Marta gave her father fits him like a tent. Time to exchange it, receipt in hand.",
  [
    Z("Im November hatte Marta ein Geschenk für ihren Vater gekauft: ein Trachtenhemd, rot-weiß kariert, mit Knöpfen aus Hirschhorn.", "En noviembre, Marta había comprado un regalo para su padre: una camisa tradicional bávara, de cuadros rojos y blancos, con botones de asta de ciervo.", "In November, Marta had bought a present for her father: a traditional Bavarian shirt, red-and-white check, with buttons made of stag horn."),
    Z("Am Mittwoch zog er es an. Das Hemd war riesig.", "El miércoles se la puso. La camisa era enorme.", "On Wednesday he put it on. The shirt was enormous."),
    N("Las mangas le tapaban las manos. Por el cuello habría cabido Clara. Su madre dijo que parecía una carpa del Oktoberfest. Su padre dijo que era muy cómoda y que en Triana la llevaría con orgullo. Pero para coger la taza de café tenía que remangarse tres veces.",
      "The sleeves covered his hands. Clara could have fitted through the collar. Her mother said he looked like an Oktoberfest tent. Her father said it was very comfortable and that he would wear it proudly in Triana. But to pick up his coffee cup he had to roll up his sleeves three times."),
    Z("Also gingen sie zusammen in den Trachtenladen in der Altstadt. Marta hatte den Kassenbon noch. Im Portemonnaie, in einer Plastikhülle.", "Así que fueron juntos a la tienda de trajes tradicionales del casco antiguo. Marta todavía tenía el tique. En la cartera, dentro de una funda de plástico.", "So they went together to the traditional clothing shop in the old town. Marta still had the receipt. In her purse, in a plastic sleeve."),
    N("Su padre la miró como se mira a un pariente que ha vuelto cambiado del extranjero. —¿Guardas los tiques en fundas de plástico? —Papá, aquí todo se guarda en fundas de plástico.",
      "Her father looked at her the way you look at a relative who has come back from abroad a different person. “You keep receipts in plastic sleeves?” “Dad, here everything goes in plastic sleeves.”"),
    Z("—Guten Tag, kann ich Ihnen behilflich sein?", "Buenas tardes, ¿puedo ayudarles en algo?", "Good afternoon, can I help you?"),
    Z("—Ja, ich habe dieses Hemd im November gekauft, aber es ist meinem Vater zu groß.", "Sí, compré esta camisa en noviembre, pero a mi padre le queda grande.", "Yes, I bought this shirt in November, but it's too big for my father."),
    Z("Die Verkäuferin sah das Hemd an. Dann den Vater. Dann wieder das Hemd.", "La dependienta miró la camisa. Luego al padre. Luego otra vez la camisa.", "The shop assistant looked at the shirt. Then at the father. Then at the shirt again."),
    Z("—Haben Sie den Kassenbon dabei?", "¿Tiene el tique?", "Do you have the receipt with you?"),
    Z("—Ja, hier. Kann ich es umtauschen? Oder muss ich es zurückgeben?", "Sí, aquí está. ¿Puedo cambiarla? ¿O tengo que devolverla?", "Yes, here. Can I exchange it? Or do I have to return it?"),
    Z("—Selbstverständlich können Sie es umtauschen. Welche Größe brauchen Sie? Das hier ist XL.", "Por supuesto que puede cambiarla. ¿Qué talla necesita? Esta es una XL.", "Of course you can exchange it. What size do you need? This one is an XL."),
    Z("—Eine Größe kleiner. Vielleicht zwei. Darf er es anprobieren?", "Una talla menos. Quizá dos. ¿Se la puede probar?", "One size smaller. Maybe two. May he try it on?"),
    Z("—Natürlich. Die Umkleidekabine ist hinten links.", "Claro. El probador está al fondo a la izquierda.", "Of course. The fitting room is at the back on the left."),
    Z("Ihr Vater verschwand mit drei Hemden in der Kabine: L, M und S.", "Su padre desapareció en el probador con tres camisas: L, M y S.", "Her father disappeared into the fitting room with three shirts: L, M and S."),
    N("Pasaron cinco minutos. Se oían ruidos: botones, codos contra la pared, un «¡ay, Dios!» en voz baja. Marta sabía algo que la dependienta no sabía: toda la mañana, en el hotel, Clara había practicado con él una frase.",
      "Five minutes went by. There were noises: buttons, elbows against the wall, a muttered “oh, Lord!”. Marta knew something the shop assistant didn't: all morning at the hotel, Clara had been practising one sentence with him."),
    Z("Dann ging der Vorhang auf. Ihr Vater stand da, im roten Hemd, Größe M, die Hände in den Hüften.", "Entonces se abrió la cortina. Ahí estaba su padre, con la camisa roja, talla M, las manos en la cintura.", "Then the curtain opened. There stood her father, in the red shirt, size M, hands on his hips."),
    Z("—Das passt.", "Me queda bien.", "It fits."),
    Z("Die Verkäuferin klatschte in die Hände.", "La dependienta aplaudió.", "The shop assistant clapped her hands."),
    Z("—Sie sprechen ja Deutsch!", "¡Pero si habla usted alemán!", "Why, you speak German!"),
    N("Su padre, animado, buscó más alemán en su memoria. Solo encontró lo que había aprendido en cuarenta años de fútbol por la tele.",
      "Encouraged, her father searched his memory for more German. All he found was what he had picked up in forty years of football on the telly."),
    Z("—Das passt. Bayern München. Elfmeter!", "Me queda bien. Bayern de Múnich. ¡Penalti!", "It fits. Bayern Munich. Penalty!"),
    Z("Die Verkäuferin lachte so sehr, dass sie sich setzen musste. Dann schenkte sie ihm ein rotes Tuch für die Hemdtasche, »für den Herrn Fußballer«.", "La dependienta se rio tanto que tuvo que sentarse. Luego le regaló un pañuelo rojo para el bolsillo de la camisa, «para el señor futbolista».", "The shop assistant laughed so much she had to sit down. Then she gave him a red handkerchief for his shirt pocket, “for the footballer”."),
    N("Desde ese momento, su padre usó su frase para todo. La cerveza: «Das passt». El tranvía con retraso: «Das passt». Clara manchada de mostaza: «Das passt».",
      "From then on, her father used his sentence for everything. The beer: “Das passt.” The late tram: “Das passt.” Clara covered in mustard: “Das passt.”"),
    Z("Am Abend lernte er von Jonas die bayerische Version: »Passt schon.« Er übte bis Mitternacht.", "Por la noche, Jonas le enseñó la versión bávara: «Passt schon». Estuvo practicando hasta medianoche.", "In the evening, Jonas taught him the Bavarian version: “Passt schon.” He practised until midnight.")
  ]),

  // ── Station 16 · WETTER (A2) ──────────────────────────────────────────
  S("aufbau", 16, "wetter", "Kommt aufs Wetter an",
    "¿Al lago Tegernsee el sábado? Depende del tiempo. La previsión del móvil dice una cosa y el barómetro del señor Brandl… por una vez, lo mismo.",
    "To the Tegernsee on Saturday? It depends on the weather. The forecast on the phone says one thing and Herr Brandl's barometer… for once, the same.",
  [
    Z("Am Donnerstagabend saßen alle in der WG-Küche: die Familie, Aylin, Jonas und ein großer Topf Linsen. Draußen regnete es leise gegen das Fenster.", "El jueves por la noche estaban todos en la cocina del piso: la familia, Aylin, Jonas y una olla grande de lentejas. Fuera, la lluvia golpeaba suavemente la ventana.", "On Thursday evening everyone was sitting in the kitchen of the flat: the family, Aylin, Jonas and a big pot of lentils. Outside, the rain was tapping softly against the window."),
    N("Las lentejas eran de su madre, que no se fiaba de la cocina alemana desde que había probado una salchicha blanca en el desayuno. «¿Salchichas a las diez de la mañana? ¿Y peladas?».",
      "The lentils were her mother's. She hadn't trusted German cooking since she had tried a white sausage at breakfast. “Sausages at ten in the morning? And you peel them?”"),
    Z("—Wollen wir am Samstag an den See fahren? An den Tegernsee?", "¿Vamos al lago el sábado? ¿Al Tegernsee?", "Shall we go to the lake on Saturday? To the Tegernsee?"),
    Z("—Kommt aufs Wetter an. Hast du die Vorhersage gesehen?", "Depende del tiempo. ¿Has visto la previsión?", "It depends on the weather. Have you seen the forecast?"),
    Z("Jonas sah auf sein Handy.", "Jonas miró el móvil.", "Jonas looked at his phone."),
    Z("—Vormittags soll es Schauer geben. Und in den Bergen vielleicht Schnee.", "Por la mañana va a haber chubascos. Y en la montaña, a lo mejor nieve.", "There are supposed to be showers in the morning. And maybe snow in the mountains."),
    N("Clara oyó «Schnee» y se levantó de un salto. Tenía doce años y no había visto la nieve nunca. Solo en la tele y en las bolas de cristal.",
      "Clara heard “Schnee” and jumped up. She was twelve and had never seen snow. Only on television and in snow globes."),
    Z("—Und am Nachmittag?", "¿Y por la tarde?", "And in the afternoon?"),
    Z("—Da klart es wohl auf. Soll sonnig werden.", "Por la tarde parece que despeja. Dicen que va a hacer sol.", "It'll probably clear up then. It's supposed to be sunny."),
    Z("—Dann fahren wir erst mittags. Kannst du uns abholen?", "Entonces salimos a mediodía. ¿Puedes venir a buscarnos?", "Then we'll leave at midday. Can you pick us up?"),
    Z("—Klar. Ich hole euch um elf am Hotel ab.", "Claro. Os recojo a las once en el hotel.", "Sure. I'll pick you up at eleven at the hotel."),
    Z("Da klopfte es an der Tür. Herr Brandl stand im Flur, in Hausschuhen, mit seinem Barometer unter dem Arm.", "En ese momento llamaron a la puerta. El señor Brandl estaba en el rellano, en zapatillas, con su barómetro bajo el brazo.", "Just then there was a knock at the door. Herr Brandl stood on the landing, in his slippers, with his barometer under his arm."),
    Z("—Guten Abend. Entschuldigung, die Wände in diesem Haus sind dünn.", "Buenas noches. Perdonen, las paredes de esta casa son muy finas.", "Good evening. Excuse me, the walls in this building are thin."),
    Z("—Ich habe »Tegernsee« gehört. Das Barometer steigt. Am Samstag früh Regen, mittags wird es schön.", "He oído «Tegernsee». El barómetro sube. El sábado temprano, lluvia; a mediodía, buen tiempo.", "I heard “Tegernsee”. The barometer is rising. Rain early on Saturday, nice weather by midday."),
    Z("»Das Handy sagt dasselbe«, sagte Jonas.", "«El móvil dice lo mismo», dijo Jonas.", "“The phone says the same,” said Jonas."),
    Z("—Das Handy hat das vom Barometer.", "El móvil lo ha copiado del barómetro.", "The phone got that from the barometer."),
    N("Marta se acordó de octubre: el señor Brandl había anunciado lluvia, ella se había reído y había vuelto a casa calada hasta los huesos. Nunca más.",
      "Marta remembered October: Herr Brandl had forecast rain, she had laughed and had come home soaked to the skin. Never again."),
    Z("—Herr Brandl, ich glaube Ihnen. Ich lache nie wieder.", "Señor Brandl, le creo. No me vuelvo a reír nunca.", "Herr Brandl, I believe you. I'll never laugh again."),
    N("Su padre quiso saber qué decía el aparato. Después le explicó al señor Brandl, con Marta de intérprete, que en Sevilla solo hay dos previsiones: «calor» y «mucho calor».",
      "Her father wanted to know what the device said. Then he explained to Herr Brandl, with Marta interpreting, that in Seville there are only two forecasts: “hot” and “very hot”."),
    Z("Herr Brandl dachte lange nach.", "El señor Brandl se quedó pensando un buen rato.", "Herr Brandl thought about it for a long time."),
    Z("—Dann braucht man in Sevilla kein Barometer. Die armen Leute.", "Entonces en Sevilla no hace falta barómetro. Pobre gente.", "So in Seville you don't need a barometer. The poor things."),
    Z("»Nehmt sicherheitshalber eine Jacke mit«, sagte Jonas. »Am See ist es kalt.«", "«Llevaos una chaqueta, por si acaso», dijo Jonas. «En el lago hace frío».", "“Take a jacket just in case,” said Jonas. “It's cold by the lake.”"),
    Z("—Eine Jacke? Ich nehme drei.", "¿Una chaqueta? Yo me llevo tres.", "One jacket? I'm taking three."),
    N("Su madre la miró con orgullo. Por fin alguien en Alemania pensaba como ella.",
      "Her mother looked at her proudly. At last, someone in Germany thought the way she did."),
    Z("Herr Brandl klopfte zweimal auf das Glas. Der Zeiger zitterte und blieb stehen.", "El señor Brandl dio dos golpecitos en el cristal. La aguja tembló y se quedó quieta.", "Herr Brandl tapped the glass twice. The needle trembled and stood still."),
    Z("—Das Barometer lügt nie.", "El barómetro nunca miente.", "The barometer never lies.")
  ]),

  // ── Station 17 · BAHNHOF (A2) ─────────────────────────────────────────
  S("aufbau", 17, "bahnhof", "Anschluss verpasst",
    "Retraso, transbordo en Holzkirchen, enlace perdido por un minuto. Una hora de espera bajo la nieve… y una tuba.",
    "A delay, a change at Holzkirchen, a connection missed by one minute. An hour's wait in the snow… and a tuba.",
  [
    Z("Am Samstag regnete es vormittags. Genau wie vorhergesagt.", "El sábado por la mañana llovió. Tal y como estaba previsto.", "On Saturday morning it rained. Exactly as forecast."),
    Z("Um halb zwölf standen alle am Hauptbahnhof. Jonas hatte die Fahrkarten gekauft: ein Gruppenticket für ganz Bayern.", "A las once y media estaban todos en la estación central. Jonas había comprado los billetes: un billete de grupo para toda Baviera.", "At half past eleven they were all at the main station. Jonas had bought the tickets: a group ticket for the whole of Bavaria."),
    Z("Der Zug fuhr pünktlich ab. Marta sah ihren Vater an: »Siehst du? Deutschland.«", "El tren salió puntual. Marta miró a su padre: «¿Ves? Alemania».", "The train left on time. Marta looked at her father: “See? Germany.”"),
    Z("Nach zehn Minuten blieb der Zug stehen. Mitten auf der Strecke. Zwischen zwei Feldern.", "A los diez minutos, el tren se paró. En plena vía. Entre dos campos.", "After ten minutes, the train stopped. In the middle of the line. Between two fields."),
    Z("Aus dem Lautsprecher kam eine Stimme: »Wegen einer Störung im Betriebsablauf hat unser Zug zwanzig Minuten Verspätung.«", "Por el altavoz se oyó una voz: «Debido a una incidencia en el servicio, nuestro tren lleva veinte minutos de retraso».", "A voice came over the loudspeaker: “Due to an operational disruption, our train is running twenty minutes late.”"),
    Z("»Der berühmteste Satz in Deutschland«, sagte Jonas.", "«La frase más famosa de Alemania», dijo Jonas.", "“The most famous sentence in Germany,” said Jonas."),
    N("Su padre, en cambio, estaba encantado. Por fin algo como en casa. Le dio una palmada en la rodilla a Jonas, como si el retraso fuera un regalo de bienvenida.",
      "Her father, on the other hand, was delighted. At last, something just like home. He patted Jonas on the knee, as if the delay were a welcome present."),
    Z("Marta stand auf und ging zur Zugbegleiterin.", "Marta se levantó y fue a hablar con la revisora.", "Marta got up and went to the conductor."),
    Z("—Entschuldigung, unser Zug hat zwanzig Minuten Verspätung. Wir müssen umsteigen.", "Perdone, nuestro tren lleva veinte minutos de retraso. Tenemos que hacer transbordo.", "Excuse me, our train is twenty minutes late. We have to change."),
    Z("—Wann müssen Sie umsteigen?", "¿Cuándo tienen que hacer transbordo?", "When do you have to change?"),
    Z("—In Holzkirchen, um 12:21 Uhr.", "En Holzkirchen, a las doce y veintiuno.", "At Holzkirchen, at 12:21."),
    Z("—Das wird knapp. Der Anschluss wartet nicht.", "Va a ir muy justo. El enlace no espera.", "That'll be tight. The connection won't wait."),
    Z("—Und wenn wir ihn verpassen?", "¿Y si lo perdemos?", "And if we miss it?"),
    Z("—Dann nehmen Sie den nächsten Zug. Ihre Fahrkarte gilt. Der nächste fährt ungefähr eine Stunde später.", "Entonces cogen el siguiente. Su billete sigue valiendo. El siguiente sale más o menos una hora después.", "Then you take the next train. Your ticket is still valid. The next one leaves about an hour later."),
    Z("Um 12:22 Uhr hielten sie in Holzkirchen. Auf dem Gleis gegenüber fuhr gerade ihr Anschluss ab.", "A las doce y veintidós pararon en Holzkirchen. En la vía de enfrente, su enlace estaba saliendo.", "At 12:22 they pulled into Holzkirchen. On the platform opposite, their connection was just leaving."),
    Z("Eine Minute. Sie hatten ihn um eine Minute verpasst.", "Un minuto. Lo habían perdido por un minuto.", "One minute. They had missed it by one minute."),
    N("Su padre miró cómo se alejaban las luces rojas del tren y dijo, con mucho respeto: —Qué puntuales son cuando se van.",
      "Her father watched the red lights of the train disappearing and said, with great respect: “How punctual they are when they leave.”"),
    N("El andén era pequeño. El quiosco, cerrado. El viento venía directamente de los Alpes, sin parar en ningún sitio. Y entonces, despacio, empezó a nevar.",
      "The platform was small. The kiosk was closed. The wind came straight from the Alps, without stopping anywhere. And then, slowly, it began to snow."),
    N("Clara se quedó quieta, con la boca abierta, cazando copos con la lengua. Su madre lo grababa todo con el móvil. Marta se puso la tercera chaqueta.",
      "Clara stood still, mouth open, catching snowflakes on her tongue. Her mother filmed everything on her phone. Marta put on her third jacket."),
    Z("Auf der Bank saß ein Mann in Tracht, mit Filzhut. Neben ihm stand ein riesiger schwarzer Koffer.", "En el banco había un hombre vestido con traje tradicional y sombrero de fieltro. A su lado, un estuche negro enorme.", "On the bench sat a man in traditional dress, with a felt hat. Next to him stood a huge black case."),
    Z("—Wir spielen heute Abend in Gmund. Weihnachtskonzert. Die anderen sind schon dort.", "Esta noche tocamos en Gmund. Concierto de Navidad. Los demás ya están allí.", "We're playing in Gmund tonight. Christmas concert. The others are already there."),
    Z("—Haben Sie auch den Anschluss verpasst?", "¿Usted también ha perdido el enlace?", "Did you miss the connection too?"),
    Z("—Jedes Jahr. Seit vierzig Jahren.", "Todos los años. Desde hace cuarenta años.", "Every year. For forty years."),
    Z("Dann öffnete er den Koffer und nahm eine Tuba heraus. Und er spielte »O Tannenbaum«. Langsam, tief und ein bisschen schief.", "Luego abrió el estuche y sacó una tuba. Y tocó «O Tannenbaum». Despacio, grave y un poco desafinado.", "Then he opened the case and took out a tuba. And he played “O Tannenbaum”. Slowly, deep and a little out of tune."),
    N("Su padre empezó a tararear. Luego a cantar, en español: «Oh, árbol de Navidad…». Dos señoras que esperaban cantaban en alemán. Clara bailaba en la nieve. Un andén, dos idiomas, una canción y una tuba.",
      "Her father began to hum. Then to sing, in Spanish: “Oh, árbol de Navidad…” Two women who were waiting sang in German. Clara danced in the snow. One platform, two languages, one song and a tuba."),
    Z("Der nächste Zug kam um 13:21 Uhr. Auf die Minute.", "El siguiente tren llegó a las trece y veintiuno. Al minuto.", "The next train arrived at 13:21. To the minute."),
    Z("»Siehst du?«, sagte Jonas. »Pünktlich.«", "«¿Ves?», dijo Jonas. «Puntual».", "“See?” said Jonas. “On time.”"),
    Z("—Eine Stunde zu spät. Aber pünktlich.", "Una hora tarde. Pero puntual.", "An hour late. But on time.")
  ]),

  // ── Station 18 · RESTAURANT (A2) ──────────────────────────────────────
  S("aufbau", 18, "restaurant", "Etwas Leichteres",
    "En la cervecería del Tegernsee, el asado es contundente, el pescado del lago da para dos y Marta paga con su primer sueldo.",
    "At the brewery inn on the Tegernsee, the roast is hearty, the lake fish is plenty for two and Marta pays with her first salary.",
  [
    Z("Das Bräustüberl am Tegernsee war voll, laut und warm. Lange Holztische, große Bierkrüge, Kellnerinnen im Dirndl.", "La cervecería del Tegernsee estaba llena, había mucho ruido y hacía calor. Mesas largas de madera, jarras de cerveza enormes, camareras con dirndl.", "The brewery inn on the Tegernsee was full, noisy and warm. Long wooden tables, big beer mugs, waitresses in dirndls."),
    N("Fuera, el lago era gris azulado y las montañas estaban blancas. Dentro, Marta se quitó las tres chaquetas. Era la segunda vez en diciembre.",
      "Outside, the lake was bluish grey and the mountains were white. Inside, Marta took off all three jackets. It was the second time in December."),
    Z("—Grüß Gott. Haben Sie schon gewählt?", "Buenas tardes. ¿Ya han elegido?", "Good afternoon. Have you decided yet?"),
    Z("—Noch nicht. Was ist denn Ihre Spezialität?", "Todavía no. ¿Cuál es su especialidad?", "Not yet. What's your speciality?"),
    Z("—Der Schweinebraten mit Knödeln. Sehr deftig, aber gut.", "El asado de cerdo con albóndigas de pan. Muy contundente, pero bueno.", "The roast pork with dumplings. Very hearty, but good."),
    N("Su padre ya había decidido al oír «Schwein». Un hombre de Triana no le dice que no a un cerdo asado.",
      "Her father had already decided the moment he heard “Schwein”. A man from Triana doesn't say no to roast pork."),
    Z("»Was ist ein Knödel?«, fragte Clara.", "«¿Qué es un Knödel?», preguntó Clara.", "“What's a Knödel?” asked Clara."),
    Z("»Ein Semmelknödel ist eine Kugel aus alten Semmeln«, sagte Jonas.", "«Un Semmelknödel es una bola hecha de panecillos duros», dijo Jonas.", "“A Semmelknödel is a ball made of old bread rolls,” said Jonas."),
    Z("»Aus alten Brötchen«, sagte Marta.", "«De panecillos duros», dijo Marta.", "“Of old rolls,” said Marta."),
    Z("—Es gibt keine Brötchenknödel. Siehst du? Die Sprache hat entschieden.", "No existen los Brötchenknödel. ¿Lo ves? El idioma ha decidido.", "There's no such thing as Brötchenknödel. You see? The language has decided."),
    N("Marta no contestó. Esa noche, en la lista de la nevera, Jonas sumaría un punto más. Lo sabía.",
      "Marta didn't answer. That night, on the list on the fridge, Jonas would add another point. She knew it."),
    Z("—Gibt es etwas Leichteres? Meine Mutter und meine Schwester möchten teilen.", "¿Hay algo más ligero? Mi madre y mi hermana quieren compartir.", "Is there anything lighter? My mother and my sister would like to share."),
    Z("—Dann empfehle ich die Renke mit Gemüse. Das ist ein Fisch aus dem See. Die Portion reicht für zwei.", "Entonces les recomiendo la Renke con verduras. Es un pescado del lago. La ración da para dos.", "Then I'd recommend the whitefish with vegetables. It's a fish from the lake. The portion is plenty for two."),
    Z("—Sind da Nüsse drin?", "¿Lleva frutos secos?", "Are there any nuts in it?"),
    Z("—Nein. Nur Butter, Petersilie und Zitrone.", "No. Solo mantequilla, perejil y limón.", "No. Just butter, parsley and lemon."),
    Z("Das Essen kam auf riesigen Tellern. Ihr Vater fragte die Kellnerin nach dem Rezept, auf Andalusisch. Die Kellnerin antwortete auf Bayerisch.", "La comida llegó en platos enormes. Su padre le pidió la receta a la camarera, en andaluz. La camarera le contestó en bávaro.", "The food arrived on huge plates. Her father asked the waitress for the recipe, in Andalusian. The waitress answered in Bavarian."),
    Z("Beide nickten viel. Keiner verstand ein Wort. Beide waren sehr zufrieden.", "Los dos asintieron mucho. Ninguno entendió una palabra. Los dos quedaron muy satisfechos.", "They both nodded a lot. Neither understood a word. Both were very satisfied."),
    Z("Hinterher rief Marta die Kellnerin.", "Después, Marta llamó a la camarera.", "Afterwards, Marta called the waitress over."),
    Z("—Könnten wir bitte zahlen?", "¿Podríamos pagar, por favor?", "Could we pay, please?"),
    Z("—Zusammen oder getrennt?", "¿Junto o por separado?", "Together or separately?"),
    N("Su padre ya tenía la cartera en la mano. En Sevilla, la cuenta es una batalla, y él llevaba cuarenta años ganándola.",
      "Her father already had his wallet in his hand. In Seville, the bill is a battle, and he had been winning it for forty years."),
    Z("—Getrennt, bitte. Ich zahle für mich, meine Eltern und meine Schwester.", "Por separado, por favor. Yo pago lo mío, lo de mis padres y lo de mi hermana.", "Separately, please. I'll pay for myself, my parents and my sister."),
    Z("—Dann ist das ja zusammen.", "Entonces es todo junto.", "Then that's together."),
    Z("—Nein. Getrennt von ihm.", "No. Por separado de él.", "No. Separately from him."),
    Z("Marta zeigte auf Jonas.", "Marta señaló a Jonas.", "Marta pointed at Jonas."),
    Z("»Passt schon«, sagte Jonas und lachte.", "«Vale, vale», dijo Jonas, y se rio.", "“Fair enough,” said Jonas, and laughed."),
    N("Su padre protestó. Una hija que invita a su padre: eso en Triana se ve una vez en la vida. —Papá, déjame. Es mi primer sueldo. Había llegado el treinta de noviembre: gracias a la Steuer-ID, gracias al empadronamiento, gracias a una firma verde en Bad Tölz.",
      "Her father protested. A daughter treating her father: in Triana, you see that once in a lifetime. “Dad, let me. It's my first salary.” It had arrived on the thirtieth of November: thanks to the tax ID, thanks to the registration, thanks to a green signature in Bad Tölz."),
    Z("Marta zahlte bar. 87,60 Euro. Sie gab der Kellnerin neunzig.", "Marta pagó en efectivo. 87,60 euros. Le dio noventa a la camarera.", "Marta paid in cash. 87.60 euros. She gave the waitress ninety."),
    Z("—Stimmt so.", "Quédese con la vuelta.", "Keep the change."),
    N("Su padre guardó la cartera muy despacio, como quien arría una bandera. Luego, en voz baja, se lo dijo a nadie en particular: —Me invita mi hija. Mi hija.",
      "Her father put his wallet away very slowly, like someone lowering a flag. Then, quietly, he said to nobody in particular: “My daughter is treating me. My daughter.”")
  ]),

  // ── Station 19 · ARZT (A2) ────────────────────────────────────────────
  S("aufbau", 19, "arzt", "Schlimmer geworden",
    "Eisstock en el mercado navideño: el padre de Marta resbala en el hielo. Al día siguiente, el hombro está peor… y él quiere explicárselo a la médica en persona.",
    "Ice stock at the Christmas market: Marta's father slips on the ice. The next day his shoulder is worse… and he wants to explain it to the doctor himself.",
  [
    Z("Am Sonntagabend gingen alle auf den Christkindlmarkt. Es roch nach Glühwein, Zimt und gebrannten Mandeln.", "El domingo por la noche fueron todos al mercado navideño. Olía a vino caliente, a canela y a almendras garrapiñadas.", "On Sunday evening they all went to the Christmas market. It smelt of mulled wine, cinnamon and caramelised almonds."),
    N("Su madre pasó lejos del puesto de las almendras, como quien pasa lejos de un perro que muerde.",
      "Her mother gave the almond stall a wide berth, the way you'd avoid a dog that bites."),
    Z("Neben dem Markt gab es eine Eisbahn. Jonas erklärte das Eisstockschießen: Man schiebt einen schweren Stock über das Eis, so nah wie möglich an ein kleines Ziel.", "Junto al mercado había una pista de hielo. Jonas explicó el Eisstockschießen: se lanza una pieza pesada sobre el hielo, lo más cerca posible de un blanco pequeño.", "Next to the market there was an ice rink. Jonas explained ice stock sport: you slide a heavy stock across the ice, as close as possible to a small target."),
    N("—Como la petanca —dijo su padre. Llevaba cuarenta años jugando a la petanca en Triana. Cogió carrerilla. La petanca, sin embargo, no se juega sobre hielo.",
      "“Like pétanque,” said her father. He had been playing pétanque in Triana for forty years. He took a run-up. Pétanque, however, is not played on ice."),
    Z("Ihr Vater rutschte aus. Er fiel auf die rechte Schulter.", "Su padre resbaló. Se cayó sobre el hombro derecho.", "Her father slipped. He fell on his right shoulder."),
    N("—¡Estoy bien, estoy bien! —dijo desde el suelo. Y se tomó otro vino caliente para demostrarlo.",
      "“I'm fine, I'm fine!” he said from the ground. And he had another mulled wine to prove it."),
    Z("Am Montag früh war die Schulter schlimmer geworden. Er konnte den Arm nicht mehr heben.", "El lunes temprano, el hombro estaba peor. Ya no podía levantar el brazo.", "By early Monday his shoulder had got worse. He could no longer lift his arm."),
    Z("Marta rief bei ihrer Hausärztin an. Sie bekamen einen Termin um zehn.", "Marta llamó a su médica de cabecera. Les dieron cita a las diez.", "Marta rang her GP. They got an appointment at ten."),
    N("En la sala de espera, Clara practicó con él una frase. Solo una. Su padre la repitió cincuenta veces, en voz baja, como quien reza el rosario.",
      "In the waiting room, Clara practised one sentence with him. Just one. Her father repeated it fifty times, under his breath, like someone saying the rosary."),
    Z("—Ah, Frau Ruiz! Die Patientin mit dem wichtigen Termin. Wie geht es Ihnen?", "¡Ah, la señora Ruiz! La paciente de la cita importante. ¿Cómo está usted?", "Ah, Frau Ruiz! The patient with the important appointment. How are you?"),
    Z("—Mir geht es gut, danke. Heute ist mein Vater der Patient.", "Yo estoy bien, gracias. Hoy el paciente es mi padre.", "I'm fine, thank you. Today my father is the patient."),
    Z("—Erzählen Sie mal, was ist denn passiert?", "Cuénteme, ¿qué ha pasado?", "Tell me, what happened?"),
    Z("Ihr Vater stand auf. Er holte tief Luft.", "Su padre se levantó. Respiró hondo.", "Her father stood up. He took a deep breath."),
    Z("—Ich … bin … gestürzt.", "Me… he… caído.", "I… have… fallen."),
    N("Y ahí se acabó el alemán. Marta siguió.",
      "And that was the end of his German. Marta took over."),
    Z("—Gestern Abend, auf dem Eis. Und heute ist die Schulter schlimmer geworden.", "Anoche, en el hielo. Y hoy el hombro está peor.", "Yesterday evening, on the ice. And today the shoulder has got worse."),
    Z("—Nimmt er zurzeit Medikamente?", "¿Toma algún medicamento ahora mismo?", "Is he taking any medication at the moment?"),
    Z("—Nur Schmerztabletten. Gegen Penizillin ist er allergisch.", "Solo analgésicos. Es alérgico a la penicilina.", "Only painkillers. He's allergic to penicillin."),
    Z("—Gut, das notiere ich. Wir machen erst mal ein Röntgenbild. Hier ist die Überweisung. Die Radiologie ist gleich gegenüber.", "Bien, lo apunto. Primero vamos a hacer una radiografía. Aquí tiene el volante. Radiología está justo enfrente.", "Fine, I'll make a note of that. First we'll do an X-ray. Here's the referral. Radiology is just across the road."),
    N("Una hora después volvieron con la radiografía. Su padre la miraba a contraluz como si fuera la foto de un nieto.",
      "An hour later they came back with the X-ray. Her father held it up to the light as if it were a photo of a grandchild."),
    Z("—Nichts gebrochen. Nur eine Prellung. Eine Woche die Schlinge tragen und nicht mehr aufs Eis.", "No hay nada roto. Solo una contusión. Una semana con el cabestrillo y nada de volver al hielo.", "Nothing broken. Just a bruise. Wear the sling for a week and no more ice."),
    Z("Sie legte ihm die Schlinge um den Arm. Da sagte ihr Vater, ganz langsam:", "Le puso el cabestrillo. Entonces su padre dijo, muy despacio:", "She put the sling round his arm. Then her father said, very slowly:"),
    Z("—Die Schulter … ist … schlimmer geworden.", "El hombro… está… peor.", "The shoulder… has… got worse."),
    Z("—Sie sprechen ja schon im Perfekt!", "¡Pero si ya habla usted en pretérito perfecto!", "Why, you're already speaking in the perfect tense!"),
    N("Marta le explicó que el Perfekt era un tiempo verbal. Su padre solo había entendido «perfecto». Salió de la consulta convencido de que su alemán era perfecto. Nadie le corrigió.",
      "Marta explained that the Perfekt was a verb tense. Her father had only understood “perfect”. He left the surgery convinced that his German was perfect. Nobody corrected him."),
    N("Jonas le llevó el abrigo todo el día, con la cara de un perro que ha roto un jarrón.",
      "Jonas carried his coat for him all day, with the face of a dog that has broken a vase.")
  ]),

  // ── Station 20 · FAMILIE (A2) ─────────────────────────────────────────
  S("aufbau", 20, "familie", "Heimweh und Fernweh",
    "Última noche: fiesta de Navidad en el piso, todos los vecinos y una pregunta sobre la infancia. El alemán tiene una palabra para añorar la casa… y otra para añorar lo lejano.",
    "The last evening: a Christmas party in the flat, all the neighbours and a question about childhood. German has a word for longing for home… and another for longing for far away.",
  [
    Z("Am letzten Abend gab es in der WG eine Weihnachtsfeier. Diesmal kamen alle.", "La última noche hubo una fiesta de Navidad en el piso. Esta vez vinieron todos.", "On the last evening there was a Christmas party in the flat. This time everyone came."),
    N("El señor Brandl, con vino caliente casero. Vroni, con una rueda de queso de montaña. La señora Schmid, con galletas sin frutos secos y sin delantal: al principio nadie la reconoció. Gerti, con vestido de fiesta y el mismo rojo en los labios. Aylin, con el baklava de su madre, que se quedó en la otra punta de la mesa, lejos de Rocío. Y una postal de Bad Tölz, en tinta verde: «Feliz Navidad a los españoles. Rosi».",
      "Herr Brandl, with home-made mulled wine. Vroni, with a wheel of mountain cheese. Frau Schmid, with nut-free biscuits and without her apron: at first nobody recognised her. Gerti, in a party dress and the same red on her lips. Aylin, with her mother's baklava, which stayed at the far end of the table, away from Rocío. And a postcard from Bad Tölz, in green ink: “Merry Christmas to the Spaniards. Rosi.”"),
    Z("Ihr Vater machte Tortilla. Mit einem Arm. Ihre Mutter machte Salmorejo mit Tomaten aus dem Supermarkt. Sie schimpfte über die Tomaten.", "Su padre hizo tortilla. Con un solo brazo. Su madre hizo salmorejo con tomates del supermercado. Y se quejó de los tomates.", "Her father made tortilla. With one arm. Her mother made salmorejo with supermarket tomatoes. She grumbled about the tomatoes."),
    Z("Nach dem Essen fragte Vroni:", "Después de cenar, Vroni preguntó:", "After the meal, Vroni asked:"),
    Z("—Marta, ich darf doch du sagen, oder? Wo hast du eigentlich als Kind gewohnt? In Sevilla?", "Marta, te puedo tutear, ¿verdad? ¿Y tú dónde vivías de pequeña? ¿En Sevilla?", "Marta, we can be on first-name terms, can't we? Where did you actually live as a child? In Seville?"),
    Z("—Nein. Wir haben in einem kleinen Dorf gewohnt, eine halbe Stunde von Sevilla. Mit Orangenbäumen und einer Kirche.", "No. Vivíamos en un pueblo pequeño, a media hora de Sevilla. Con naranjos y una iglesia.", "No. We lived in a small village, half an hour from Seville. With orange trees and a church."),
    Z("—Und war die ganze Familie dort?", "¿Y estaba allí toda la familia?", "And was the whole family there?"),
    Z("—Ja. Sonntags haben wir uns bei meiner Tante Encarna getroffen. Zwanzig Leute, ein Tisch, viel Lärm.", "Sí. Los domingos nos reuníamos en casa de mi tía Encarna. Veinte personas, una mesa, mucho ruido.", "Yes. On Sundays we got together at my aunt Encarna's. Twenty people, one table, a lot of noise."),
    Z("—Wie schön. Sind sie noch da?", "Qué bonito. ¿Siguen allí?", "How lovely. Are they still there?"),
    Z("—Meine Tante ja. Aber als ich vierzehn war, sind wir umgezogen. Mein Vater hat eine Bar in Triana aufgemacht. Und meine Cousins sind weggezogen: nach Madrid, nach London, nach Lyon.", "Mi tía, sí. Pero cuando yo tenía catorce años nos mudamos. Mi padre abrió un bar en Triana. Y mis primos se fueron: a Madrid, a Londres, a Lyon.", "My aunt, yes. But when I was fourteen we moved. My father opened a bar in Triana. And my cousins moved away: to Madrid, to London, to Lyon."),
    Z("»Früher war das bei uns genauso«, sagte Herr Brandl. »Als Kind habe ich in einem Dorf in Niederbayern gewohnt. Damals hatten wir kein Barometer. Damals hatten wir das Knie von meinem Großvater.«", "«Antes, en mi casa, era igual», dijo el señor Brandl. «De niño vivía en un pueblo de la Baja Baviera. Entonces no teníamos barómetro. Teníamos la rodilla de mi abuelo».", "“It used to be the same for us,” said Herr Brandl. “As a child I lived in a village in Lower Bavaria. Back then we didn't have a barometer. Back then we had my grandfather's knee.”"),
    Z("»Und das Knie hat nie gelogen?«, fragte Gerti.", "«¿Y la rodilla nunca mentía?», preguntó Gerti.", "“And the knee never lied?” asked Gerti."),
    Z("—Nie. Nur einmal, 1963.", "Nunca. Solo una vez, en 1963.", "Never. Only once, in 1963."),
    Z("»Ich bin in Giesing aufgewachsen«, sagte Gerti. »Das ist auch ein Dorf. Nur mit Tram.«", "«Yo me crie en Giesing», dijo Gerti. «Eso también es un pueblo. Pero con tranvía».", "“I grew up in Giesing,” said Gerti. “That's a village too. Just with a tram.”"),
    N("Todos se rieron. Marta traducía para sus padres, Aylin para nadie: Clara ya entendía bastante. Su padre oyó «Tram» y miró a Jonas con cariño, como a un colega.",
      "Everyone laughed. Marta translated for her parents, Aylin for nobody: Clara understood quite a lot by now. Her father heard “Tram” and looked fondly at Jonas, as at a colleague."),
    Z("Später, am Fenster, fragte Aylin leise:", "Más tarde, junto a la ventana, Aylin le preguntó en voz baja:", "Later, at the window, Aylin asked quietly:"),
    Z("—Vermisst du dein Dorf?", "¿Echas de menos tu pueblo?", "Do you miss your village?"),
    N("Marta pensó en el azahar de marzo, que huele toda la calle. En la cocina de la tía Encarna. En las campanas del domingo. Luego miró a su alrededor: la tortilla, la rueda de queso, el barómetro del señor Brandl en el aparador, el pintalabios de Gerti en una copa.",
      "Marta thought of the orange blossom in March, which scents the whole street. Of Aunt Encarna's kitchen. Of the Sunday bells. Then she looked around her: the tortilla, the wheel of cheese, Herr Brandl's barometer on the sideboard, Gerti's lipstick on a glass."),
    Z("—Ja. Manchmal vermisse ich es. Heute Abend sehr.", "Sí. A veces lo echo de menos. Esta noche, mucho.", "Yes. Sometimes I miss it. Very much tonight."),
    N("Aylin le explicó que el alemán tiene una palabra para eso: Heimweh, «dolor de casa». Y otra para lo contrario: Fernweh, «dolor de lejos», las ganas de estar en otro sitio. Marta pensó que era muy alemán tener una palabra exacta para cada dolor.",
      "Aylin explained that German has a word for that: Heimweh, “home-ache”. And another for the opposite: Fernweh, “far-ache”, the longing to be somewhere else. Marta thought it was very German to have an exact word for every ache."),
    Z("Am nächsten Morgen fuhr Gerti die Familie zum Flughafen. Die Kiste mit den Orangen war leer.", "A la mañana siguiente, Gerti llevó a la familia al aeropuerto. La caja de naranjas estaba vacía.", "The next morning, Gerti drove the family to the airport. The orange box was empty."),
    Z("Am Abend war die WG sehr still. Am Kühlschrank hing die Liste: Semmel 44, Brötchen 7.", "Por la noche, el piso estaba muy silencioso. En la nevera seguía la lista: Semmel 44, Brötchen 7.", "That evening the flat was very quiet. The list hung on the fridge: Semmel 44, Brötchen 7."),
    Z("Heute hatte Marta Heimweh. Das wusste sie.", "Hoy Marta sentía Heimweh. Lo sabía.", "Today Marta felt homesick. She knew that."),
    Z("Und eines Tages, in Sevilla, würde sie Fernweh haben. Nach München.", "Y algún día, en Sevilla, sentiría Fernweh. Por Múnich.", "And one day, in Seville, she would feel Fernweh. For Munich.")
  ]),

  /* ═════════════════════════════════════════════════════════════════════
     EPILOG · ANWENDUNG · ganz auf Deutsch, ohne Brücke
     ═════════════════════════════════════════════════════════════════════ */
  S("anwendung", 21, null, "Servus",
    "Julio. Una semana antes de las vacaciones en Sevilla: unos panecillos para el avión, una tarde en el Isar y un taxi que termina donde empezó todo. Todo en alemán.",
    "July. A week before the holidays in Seville: rolls for the plane, an evening by the Isar and a taxi ride that ends where it all began. Entirely in German.",
  [
    P("Im Juli war München eine andere Stadt. Die Biergärten waren voll, die Isar war grün und schnell, und auf den Kiesbänken lagen Studenten, Hunde und Großväter in der Sonne. Um zehn Uhr abends war es noch hell. Marta trug ein T-Shirt. Nur ein T-Shirt. Jonas hatte ein Foto davon gemacht und an den Kühlschrank gehängt, neben die Liste."),
    P("Am Freitag flog sie nach Sevilla, für den Sommer. Im September fing ihr zweites Jahr an, und ihr Zimmer in Haidhausen blieb ihr Zimmer. Frau Ostermeier hatte den neuen Mietvertrag schon unterschrieben, natürlich mit dem grünen Stift. Dazu hatte sie eine Karte geschrieben: »Für die Spanierin, die keine Spanierin mehr ist. Ein bisserl schon. Rosi.«"),
    P("Trotzdem lag der Koffer seit drei Tagen offen auf dem Boden. Marta packte ein und packte wieder aus. Butterplätzchen für ihre Mutter, nussfrei. Ein Trambahn-Regenschirm für Clara, sehr hässlich, ein Geschenk von Jonas. Und die Plastikhülle mit der Meldebescheinigung. Die nahm sie immer mit. Andere Menschen haben einen Glücksbringer. Marta hatte einen Stempel."),
    P("Am Donnerstagmorgen ging sie ein letztes Mal zu Frau Schmid."),
    P("—Zwei Semmeln, bitte. Zum Mitnehmen."),
    P("Frau Schmid legte drei Semmeln in die Tüte. Dann sah sie Marta über die Brille an."),
    P("—Die dritte ist für das Flugzeug. Und im September sagen Sie wieder Semmel. Nicht Brötchen. Ich merke das."),
    P("—Versprochen."),
    P("Marta wollte zahlen, aber Frau Schmid schüttelte den Kopf und drehte sich schnell zur Kaffeemaschine. Sie schlug zweimal mit der Faust darauf, obwohl die Maschine gar nicht kaputt war."),
    P("Auf dem Viktualienmarkt wartete Vroni schon mit einem großen Stück Bergkäse, in Papier gewickelt."),
    P("—Für deinen Papa. Und sag ihm: Das passt."),
    P("Der Satz war inzwischen berühmt. Ihr Vater sagte ihn in Triana jeden Tag, zu jedem Gast, und die Gäste sagten ihn zurück. In einer kleinen Bar in Sevilla sprach man jetzt ein bisschen Deutsch. Und im Regal hinter der Theke stand eine Quittung von Gerti, im Rahmen."),
    P("Im Treppenhaus traf sie Herrn Brandl. Er trug das Barometer wie immer unter dem Arm, als ginge er mit ihm spazieren."),
    P("—Morgen wird es schön. Guter Tag zum Fliegen. Und in Sevilla?"),
    P("—In Sevilla wird es heiß."),
    P("—Ich weiß. Sehr heiß. Die armen Leute."),
    P("Am Abend saßen sie im Biergarten am Wiener Platz: Aylin, Jonas und Marta, unter einer alten Kastanie. Aylin hatte gerade eine große Prüfung bestanden und erklärte allen, dass sie jetzt fast eine richtige Ärztin war. Jonas hatte Spätschicht gehabt und roch noch ein bisschen nach Tram."),
    P("Am Nebentisch saß ein Mann mit einem Mädchen, ungefähr zwölf Jahre alt, das ein riesiges Eis aß. Marta kannte das Gesicht. Er kannte ihres auch. Es war Herr Gruber vom Bürgerbüro, ohne Krawatte und ohne Drucker. Er hob sein Glas."),
    P("—Frau Ruiz! Wie geht es der Schwester? Klara mit K?"),
    P("—Mit C, Herr Gruber. Immer noch mit C."),
    P("Er lachte, und seine Tochter wollte wissen, warum. Marta erklärte es ihr. Am Ende waren sie sich einig: Mit C ist schöner. Herr Gruber sagte, das sei Geschmackssache, aber er werde es notieren."),
    P("Aylin war wie immer die Praktische."),
    P("—Hast du alles? Pass, Ticket, Steuer-ID?"),
    P("—Ich habe sogar eine Wohnungsgeberbestätigung. Im Herzen."),
    P("Danach gingen sie hinunter an die Isar. Jonas und Aylin sprangen ins Wasser. Marta hielt nur die Füße hinein. Das Wasser hatte sechzehn Grad. Sie schrie so laut, dass am anderen Ufer ein Hund zu bellen anfing. Manche Dinge ändern sich nie."),
    P("Später, als es endlich dunkel wurde, nahm Jonas einen Stift aus der Tasche und schrieb etwas auf eine Serviette. Er gab sie Marta. Darauf stand: »Semmel 112, Brötchen 9.«"),
    P("—Ist das das Endergebnis?"),
    P("—Nein. Das ist der Zwischenstand. Im September geht es weiter."),
    P("Am Freitagmorgen stand ein Taxi vor dem Haus. Marta hatte es nicht bestellt. Am Steuer saß Gerti, mit Sonnenbrille und Lippenstift, und hupte zweimal kurz."),
    P("—Servus, Spanierin! Zum Flughafen?"),
    P("—Woher weißt du das?"),
    P("—Von der Vroni. Die Vroni weiß alles."),
    P("Gerti legte den Koffer in den Kofferraum, als wäre er leer. Die A9 war frei, kein Stau, keine Baustelle, keine Umleitung. Nach fünf Minuten machte Gerti die Klimaanlage aus, ohne zu fragen."),
    P("—Du frierst ja schon wieder."),
    P("Marta lachte. Es war Juli, es waren dreißig Grad, und sie fror. Im Oktober hatte sie in diesem Taxi gesessen und kein Wort verstanden: nicht die Stadt, nicht die Leute, nicht das längste Wort der Welt. Jetzt verstand sie fast alles. Nur warum Münchner im Juli Klimaanlagen brauchen, verstand sie immer noch nicht."),
    P("Am Terminal 2 hielt Gerti an. Marta wollte zahlen, und Gerti nahm das Geld. Dann schrieb sie langsam eine Quittung und gab sie ihr."),
    P("—Für deinen Vater. Für die Unterlagen."),
    P("Dann sah sie in den Spiegel, prüfte ihren Lippenstift und umarmte Marta fest. Auf Martas Wange blieb ein kleiner roter Fleck. Marta wischte ihn nicht weg. Sie nahm ihn mit nach Sevilla."),
    P("Am Eingang drehte sie sich noch einmal um. Gerti stand neben dem Taxi und hob die Hand. Marta suchte das richtige Wort. »Tschüss« klang nach Ende. »Auf Wiedersehen« klang nach Amt. Und dann wusste sie es. Im Oktober hatte Jonas sie mit diesem Wort begrüßt. Heute ging sie mit demselben Wort."),
    P("—Servus, Gerti!"),
    P("Denn in München heißt Servus Hallo und Tschüss zugleich. Wer Servus sagt, ist schon fast wieder da.")
  ])

  ];
})(window);

